-- Generated by node scripts/import-content.mjs; edit source JSON, then regenerate.
-- Additive, reproducible import. Existing catalog IDs and candidate history are retained.
begin;
set local standard_conforming_strings = on;

-- Open attempts must not silently switch to a new assignment or inherit its old timer.
alter table public.simulation_attempts add column if not exists superseded_at timestamptz;
update public.simulation_attempts a set superseded_at = now() from public.simulations s where s.id = a.simulation_id and a.submission_id is null and a.superseded_at is null and s.slug like 'r2w-%' and coalesce(s.reference_data->>'source_version', '') <> '20261017';
create or replace function public.finalize_simulation_attempt(
  p_attempt_id uuid, p_user_id uuid, p_content text,
  p_overall_score integer, p_overall_band text, p_criterion_scores jsonb,
  p_private_details jsonb, p_submitted_at timestamptz
) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  attempt public.simulation_attempts%rowtype;
  result_id uuid;
  duration_seconds integer;
begin
  select * into attempt from public.simulation_attempts where id = p_attempt_id for update;
  if not found or attempt.user_id <> p_user_id then
    raise exception 'Simulation attempt not found';
  end if;
  if attempt.submission_id is not null then return attempt.submission_id; end if;
  if attempt.superseded_at is not null then raise exception 'Simulation source changed; start a new attempt'; end if;
  if p_submitted_at < attempt.started_at or p_submitted_at > now() or p_content = ''
    or p_overall_score is null or p_overall_score < 0 or p_overall_score > 100 then
    raise exception 'Invalid simulation evaluation';
  end if;
  duration_seconds := floor(extract(epoch from (p_submitted_at - attempt.started_at)))::integer;
  insert into public.simulation_submissions (
    user_id, simulation_id, attempt_id, content, overall_score, overall_band,
    criterion_scores, actual_duration_seconds, submitted_at
  ) values (
    p_user_id, attempt.simulation_id, attempt.id, p_content, p_overall_score,
    p_overall_band, p_criterion_scores, duration_seconds, p_submitted_at
  ) returning id into result_id;
  insert into public.simulation_submission_evaluations(submission_id, details)
    values(result_id, coalesce(p_private_details, '{}'::jsonb));
  update public.simulation_attempts set submitted_at = p_submitted_at, submission_id = result_id where id = attempt.id;
  return result_id;
end;
$$;

-- Retain every old question/session/answer; only the new version is listed for practice.
update public.interview_sets set is_available = false, unavailable_reason = 'Bộ đề lưu trữ từ phiên bản trước; lịch sử làm bài vẫn được giữ.' where slug like 'r2w-%' and slug not like '%-20261017';
update public.interview_sets set is_available = false, unavailable_reason = 'Bộ đề mẫu cũ đã được thay bằng tài liệu dự án.' where slug in ('financial-analyst-general', 'software-engineer-general', 'commercial-bank-credit-round1', 'product-company-data-round1') and position_id is null;

insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('6d16f729-3ca3-523b-b031-9f1797fc8cd1', 'r2w-mkt-01', 'Marketing', 'Marketing Intern (Thực tập sinh Marketing)', 'Tình huống: Local Brand thời trang bán qua Fanpage (18.000 follower) và Shopee, sắp ra mắt BST Thu-Đông cho sinh viên (hoodie “Campus Fleece”). Engagement rate giảm 30% (3,0% → 2,1%); 10 bài gần nhất là ảnh sản phẩm nền trắng, chưa có kế hoạch nội dung và video ngắn.

Ràng buộc: team 2 người, không thuê KOL/studio, quay bằng điện thoại; khách hàng Gen Z 18–22 tuổi.', '## Bối cảnh

Tình huống: Local Brand thời trang bán qua Fanpage (18.000 follower) và Shopee, sắp ra mắt BST Thu-Đông cho sinh viên (hoodie “Campus Fleece”). Engagement rate giảm 30% (3,0% → 2,1%); 10 bài gần nhất là ảnh sản phẩm nền trắng, chưa có kế hoạch nội dung và video ngắn.

Ràng buộc: team 2 người, không thuê KOL/studio, quay bằng điện thoại; khách hàng Gen Z 18–22 tuổi.

## Yêu cầu nhiệm vụ

1. Kế hoạch nội dung 7 ngày dạng bảng (Ngày – Kênh – Định dạng – Ý tưởng – Mục tiêu – CTA)

2. 01 bài copywriting Facebook ≤150 từ đúng Brand Voice

3. 02 kịch bản TikTok/Reels 30s bắt trend, nêu trend và lý do chọn.', 60, 0, 'MKT-01', true, null, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","weight":15,"maxScore":15}]'::jsonb, '[{"id":"C1","label":"Độ chính xác trong quyết định/đề xuất chính","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C1-1\",\"text\":\"Kế hoạch 7 ngày đủ 3 giai đoạn (teaser → ra mắt → duy trì), mỗi ngày có kênh – định dạng – mục tiêu – CTA\",\"points\":15,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-01-C1-2\",\"text\":\"Copy đúng Product Brief: chất liệu, giá, ưu đãi 48 giờ\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"MKT-01-C1-3\",\"text\":\"· 02 kịch bản 30s: hook trong 3 giây đầu, đủ cảnh – lời – text overlay, có CTA\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C2","label":"Lý do/lập luận rõ ràng, bám sát tiêu chí","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C2-1\",\"text\":\"Mỗi lựa chọn (định dạng, trend, giờ đăng) giải thích bằng insight Gen Z sinh viên, gắn với nguyên nhân sụt tương tác (nội dung đơn điệu, thiếu video ngắn); nêu KPI kỳ vọng (VD: engagement rate ≥3,5%, lượt xem video)\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C3","label":"Xử lý sâu vấn đề phát sinh","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C3-1\",\"text\":\"Ưu đãi chỉ 48 giờ nhưng kế hoạch 7 ngày → ngày 4–7 chuyển sang social proof/UGC/review · Trend lệch tông hoặc rủi ro bản quyền nhạc → chỉnh cho hợp giọng “Shop – Cậu”, dùng nhạc thư viện thương mại · Nguồn lực hạn chế (không KOL, quay bằng điện thoại) → kịch bản đơn giản, khả thi\",\"points\":25,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":25,"maxScore":25},{"id":"C4","label":"Trình bày mạch lạc, đúng thời gian","description":"{\"checklist\":[{\"checklist_id\":\"MKT-01-C4-1\",\"text\":\"Đủ 3 yêu cầu đúng thứ tự, dùng bảng/gạch đầu dòng rõ ràng, văn phong chuyên nghiệp, hoàn thành trong 60 phút\",\"points\":15,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":15,"maxScore":15}]'::jsonb, '{"position_id":"MKT-01","position_name":"Marketing Intern (Thực tập sinh Marketing)","level":"Fresher/Junior","time_limit_minutes":60,"time_limit_source":"specified","source_version":"20261017","source_block":285,"context":"Tình huống: Local Brand thời trang bán qua Fanpage (18.000 follower) và Shopee, sắp ra mắt BST Thu-Đông cho sinh viên (hoodie “Campus Fleece”). Engagement rate giảm 30% (3,0% → 2,1%); 10 bài gần nhất là ảnh sản phẩm nền trắng, chưa có kế hoạch nội dung và video ngắn.\n\nRàng buộc: team 2 người, không thuê KOL/studio, quay bằng điện thoại; khách hàng Gen Z 18–22 tuổi.","requirements":["1. Kế hoạch nội dung 7 ngày dạng bảng (Ngày – Kênh – Định dạng – Ý tưởng – Mục tiêu – CTA)","2. 01 bài copywriting Facebook ≤150 từ đúng Brand Voice","3. 02 kịch bản TikTok/Reels 30s bắt trend, nêu trend và lý do chọn."],"rubric":[{"criterion_id":"C1","criterion_name":"Độ chính xác trong quyết định/đề xuất chính","max_points":35,"description":"- Kế hoạch 7 ngày đủ 3 giai đoạn (teaser → ra mắt → duy trì), mỗi ngày có kênh – định dạng – mục tiêu – CTA (15)\n- Copy đúng Product Brief: chất liệu, giá, ưu đãi 48 giờ (10) · 02 kịch bản 30s: hook trong 3 giây đầu, đủ cảnh – lời – text overlay, có CTA (10)\nVD: Ngày 1–2 teaser/đếm ngược; Ngày 3 mở bán kèm ưu đãi; Ngày 4-7 review, UGC, flash sale cuối.","checklist":[{"checklist_id":"MKT-01-C1-1","text":"Kế hoạch 7 ngày đủ 3 giai đoạn (teaser → ra mắt → duy trì), mỗi ngày có kênh – định dạng – mục tiêu – CTA","points":15,"scoring_source":"ai"},{"checklist_id":"MKT-01-C1-2","text":"Copy đúng Product Brief: chất liệu, giá, ưu đãi 48 giờ","points":10,"scoring_source":"ai"},{"checklist_id":"MKT-01-C1-3","text":"· 02 kịch bản 30s: hook trong 3 giây đầu, đủ cảnh – lời – text overlay, có CTA","points":10,"scoring_source":"ai"}]},{"criterion_id":"C2","criterion_name":"Lý do/lập luận rõ ràng, bám sát tiêu chí","max_points":25,"description":"Mỗi lựa chọn (định dạng, trend, giờ đăng) giải thích bằng insight Gen Z sinh viên, gắn với nguyên nhân sụt tương tác (nội dung đơn điệu, thiếu video ngắn); nêu KPI kỳ vọng (VD: engagement rate ≥3,5%, lượt xem video)","checklist":[{"checklist_id":"MKT-01-C2-1","text":"Mỗi lựa chọn (định dạng, trend, giờ đăng) giải thích bằng insight Gen Z sinh viên, gắn với nguyên nhân sụt tương tác (nội dung đơn điệu, thiếu video ngắn); nêu KPI kỳ vọng (VD: engagement rate ≥3,5%, lượt xem video)","points":25,"scoring_source":"ai"}]},{"criterion_id":"C3","criterion_name":"Xử lý sâu vấn đề phát sinh","max_points":25,"description":"Ưu đãi chỉ 48 giờ nhưng kế hoạch 7 ngày → ngày 4–7 chuyển sang social proof/UGC/review · Trend lệch tông hoặc rủi ro bản quyền nhạc → chỉnh cho hợp giọng “Shop – Cậu”, dùng nhạc thư viện thương mại · Nguồn lực hạn chế (không KOL, quay bằng điện thoại) → kịch bản đơn giản, khả thi","checklist":[{"checklist_id":"MKT-01-C3-1","text":"Ưu đãi chỉ 48 giờ nhưng kế hoạch 7 ngày → ngày 4–7 chuyển sang social proof/UGC/review · Trend lệch tông hoặc rủi ro bản quyền nhạc → chỉnh cho hợp giọng “Shop – Cậu”, dùng nhạc thư viện thương mại · Nguồn lực hạn chế (không KOL, quay bằng điện thoại) → kịch bản đơn giản, khả thi","points":25,"scoring_source":"ai"}]},{"criterion_id":"C4","criterion_name":"Trình bày mạch lạc, đúng thời gian","max_points":15,"description":"Đủ 3 yêu cầu đúng thứ tự, dùng bảng/gạch đầu dòng rõ ràng, văn phong chuyên nghiệp, hoàn thành trong 60 phút","checklist":[{"checklist_id":"MKT-01-C4-1","text":"Đủ 3 yêu cầu đúng thứ tự, dùng bảng/gạch đầu dòng rõ ràng, văn phong chuyên nghiệp, hoàn thành trong 60 phút","points":15,"scoring_source":"ai"}]}],"hard_constraints":[],"input_artifacts":[],"public_materials":[{"id":"intern-plan","title":"Kế hoạch nội dung 7 ngày","kind":"table","columns":["Ngày","Kênh","Định dạng","Ý tưởng","Mục tiêu","CTA"],"rows":[["1","","","","",""],["2","","","","",""],["3","","","","",""],["4","","","","",""],["5","","","","",""],["6","","","","",""],["7","","","","",""]],"editable":true},{"id":"marketing-product-brief","title":"Product Brief · Dữ liệu mô phỏng","kind":"table","columns":["Thông tin","Nội dung"],"rows":[["Sản phẩm","Hoodie Campus Fleece, bộ sưu tập Thu-Đông dành cho sinh viên 18–22 tuổi."],["Chất liệu","Nỉ bông: 65% cotton, 35% polyester."],["Kiểu dáng","Form rộng unisex; cỡ S, M, L, XL; màu đen, xám và nâu."],["Giá niêm yết","399.000 đồng/áo."],["Ưu đãi mở bán","Giảm 40.000 đồng/áo, còn 359.000 đồng trong 48 giờ đầu kể từ thời điểm mở bán. Hết 48 giờ trở lại giá niêm yết."],["Kênh mua hàng","Fanpage của thương hiệu và gian hàng Shopee."],["Giọng thương hiệu","Xưng hô “Shop – Cậu”, trẻ trung, gần gũi với sinh viên."],["Nguồn lực","Nhóm 2 người; quay bằng điện thoại; không thuê KOL hoặc studio."]],"editable":false,"provenance":"Dữ liệu mô phỏng bổ sung theo cho phép của chủ dự án ngày 17/10/2026; không phải tài liệu gốc Google Docs."}],"source_rubric_text":"","grading_ready":true,"source_conflicts":[],"source_total_points":100,"supplemental_source":"marketing-inputs-20261017.json","artifacts":{}}'::jsonb)
