insert into public.simulations (id, slug, industry, position_title, brief, task_instructions, estimated_minutes, min_words, position_id, is_available, unavailable_reason, rubric, grading_rubric, reference_data)
values ('ebafcd34-d832-5de9-9a31-68f555f4c1f8', 'r2w-kk-01', 'Kế toán - Kiểm toán', 'Kế toán viên', '1. Bạn là Kế toán tổng hợp (Chuyên bán lẻ đồ điện tử). Công ty áp dụng chế độ kế toán theo Thông tư 200/2014/TT-BTC, kê khai thuế GTGT theo phương pháp khấu trừ. Hôm nay là ngày 31/12/2026, bạn cần rà soát và hạch toán lô chứng từ cuối cùng để khóa sổ lập Báo cáo tài chính.

2. Dữ liệu cung cấp (Inputs): Bộ phận mua hàng và ngân hàng gửi đến cho bạn 3 chứng từ sau:

1. Chứng từ 1: Hóa đơn GTGT mua 1 chiếc ô tô 9 chỗ ngồi phục vụ cho việc đi lại của Giám đốc. Giá chưa thuế GTGT: 2.500.000.000 VNĐ, Thuế GTGT 10%: 250.000.000 VNĐ.

2. Chứng từ 2: Hóa đơn GTGT tiếp khách tại nhà hàng sang trọng, tổng thanh toán 22.000.000 VNĐ (đã bao gồm 10% VAT). Tuy nhiên, trên hóa đơn bị sai một chữ số trong Mã số thuế của công ty Alpha. (Thanh toán bằng thẻ tín dụng công ty).

3. Chứng từ 3: Giấy báo Có của Ngân hàng Vietcombank về việc nhận được thanh toán từ khách hàng nước ngoài (Công ty X). Số tiền nhận: 50.000 USD.

4. Biết rằng: Khoản phải thu của khách hàng X đang có số dư trên sổ kế toán là: 50.000 USD, tỷ giá ghi sổ là 24.200 VNĐ/USD.

5. Tỷ giá mua chuyển khoản của Vietcombank ngày 31/12/2026 là 25.100 VNĐ/USD.

6. Ngân hàng nước ngoài đã thu phí chuyển tiền trực tiếp từ số tiền này là 50 USD (Công ty Alpha chịu phí theo hợp đồng). Thực tế tiền vào tài khoản chỉ là 49.950 USD.', '## Bối cảnh

1. Bạn là Kế toán tổng hợp (Chuyên bán lẻ đồ điện tử). Công ty áp dụng chế độ kế toán theo Thông tư 200/2014/TT-BTC, kê khai thuế GTGT theo phương pháp khấu trừ. Hôm nay là ngày 31/12/2026, bạn cần rà soát và hạch toán lô chứng từ cuối cùng để khóa sổ lập Báo cáo tài chính.

2. Dữ liệu cung cấp (Inputs): Bộ phận mua hàng và ngân hàng gửi đến cho bạn 3 chứng từ sau:

1. Chứng từ 1: Hóa đơn GTGT mua 1 chiếc ô tô 9 chỗ ngồi phục vụ cho việc đi lại của Giám đốc. Giá chưa thuế GTGT: 2.500.000.000 VNĐ, Thuế GTGT 10%: 250.000.000 VNĐ.

2. Chứng từ 2: Hóa đơn GTGT tiếp khách tại nhà hàng sang trọng, tổng thanh toán 22.000.000 VNĐ (đã bao gồm 10% VAT). Tuy nhiên, trên hóa đơn bị sai một chữ số trong Mã số thuế của công ty Alpha. (Thanh toán bằng thẻ tín dụng công ty).

3. Chứng từ 3: Giấy báo Có của Ngân hàng Vietcombank về việc nhận được thanh toán từ khách hàng nước ngoài (Công ty X). Số tiền nhận: 50.000 USD.

4. Biết rằng: Khoản phải thu của khách hàng X đang có số dư trên sổ kế toán là: 50.000 USD, tỷ giá ghi sổ là 24.200 VNĐ/USD.

5. Tỷ giá mua chuyển khoản của Vietcombank ngày 31/12/2026 là 25.100 VNĐ/USD.

6. Ngân hàng nước ngoài đã thu phí chuyển tiền trực tiếp từ số tiền này là 50 USD (Công ty Alpha chịu phí theo hợp đồng). Thực tế tiền vào tài khoản chỉ là 49.950 USD.

## Yêu cầu nhiệm vụ

Xử lý chứng từ: Trình bày cách xử lý (về mặt thủ tục giấy tờ/thuế) đối với Chứng từ số 2 (Hóa đơn sai MST). Hóa đơn này có được khấu trừ thuế và tính vào chi phí hợp lý không?

Định khoản kế toán: Lập bút toán hạch toán (Nợ/Có) cho cả 3 nghiệp vụ trên.

1. Đặc biệt lưu ý: Nguyên giá tài sản cố định và Thuế GTGT được khấu trừ của Chứng từ 1 theo đúng Luật Thuế hiện hành.', 60, 0, 'KK-01', true, null, '[{"id":"C1","label":"Xử lý Chứng từ 2","weight":20,"maxScore":20},{"id":"C2","label":"Định khoản Ô tô 9 chỗ","weight":35,"maxScore":35},{"id":"C3","label":"Hạch toán chênh lệch tỷ giá & Phí ngân hàng","weight":45,"maxScore":45}]'::jsonb, '[{"id":"C1","label":"Xử lý Chứng từ 2","description":"{\"checklist\":[{\"checklist_id\":\"KK-01-C1-1\",\"text\":\"1. Xử lý Chứng từ 2 (20đ): Nêu đúng thủ tục xử lý hóa đơn điện tử sai sót (Lập biên bản điều chỉnh/Thông báo mẫu 04/SS-HĐĐT, yêu cầu xuất hóa đơn điều chỉnh). Khẳng định được: Khi chưa điều chỉnh thì chưa được khấu trừ thuế và tính chi phí hợp lệ (20đ).\",\"points\":20,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":20,"maxScore":20},{"id":"C2","label":"Định khoản Ô tô 9 chỗ","description":"{\"checklist\":[{\"checklist_id\":\"KK-01-C2-1\",\"text\":\"Nhận định đúng luật: Ô tô dưới 9 chỗ không kinh doanh vận tải chỉ được khấu trừ VAT phần trị giá 1,6 tỷ (VAT = 160 triệu) (15đ).\",\"points\":15,\"scoring_source\":\"ai\"},{\"checklist_id\":\"KK-01-C2-2\",\"text\":\"Hạch toán đúng Nợ TK 211 (Nguyên giá = 2,5 tỷ + phần VAT không được khấu trừ 90 triệu = 2.590.000.000đ) (10đ).\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"KK-01-C2-3\",\"text\":\"Hạch toán đúng Nợ TK 1332 (160 triệu) / Có TK 331 (2,75 tỷ) (10đ).\",\"points\":10,\"scoring_source\":\"ai\"}],\"hard_constraints\":[]}","keywords":[],"weight":35,"maxScore":35},{"id":"C3","label":"Hạch toán chênh lệch tỷ giá & Phí ngân hàng","description":"{\"checklist\":[{\"checklist_id\":\"KK-01-C3-1\",\"text\":\"Ghi nhận đúng phí ngân hàng: Nợ TK 642: 50 USD x 25.100 (10đ).\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"KK-01-C3-2\",\"text\":\"Ghi nhận đúng tiền thực nhận: Nợ TK 1122: 49.950 USD x 25.100 (10đ).\",\"points\":10,\"scoring_source\":\"ai\"},{\"checklist_id\":\"