insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('26b90fdf-cbfb-5194-9b6d-4dbcd8969226', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 1, 'Giới thiệu bản thân và lý do bạn muốn theo đuổi vị trí Business Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn liên quan","description":"Tiêu chí 1- Nền tảng chuyên môn liên quan (12đ): Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ, không nói chung chung.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng chuyên môn liên quan"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Phải chỉ ra đúng đặc thù công việc Business Analyst là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật, không phải lý do chung chung như “yêu thích công nghệ”.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề đúng bản chất"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, có dùng một số thuật ngữ cơ bản (yêu cầu nghiệp vụ/requirement, stakeholder).","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1- Nền tảng chuyên môn liên quan (12đ): Nêu cụ thể ngành học/dự án đã làm liên quan trực tiếp đến phân tích nghiệp vụ, không nói chung chung.
Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Phải chỉ ra đúng đặc thù công việc Business Analyst là phân tích vấn đề kinh doanh và làm cầu nối với đội kỹ thuật, không phải lý do chung chung như “yêu thích công nghệ”.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, có dùng một số thuật ngữ cơ bản (yêu cầu nghiệp vụ/requirement, stakeholder).')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('711a8dee-eb15-501c-9eb3-f5492de714c4', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 2, 'Bạn hiểu vai trò của một Business Analyst trong dự án phần mềm là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò cầu nối","description":"Tiêu chí 1 - Xác định đúng vai trò cầu nối (15đ): Nêu rõ Business Analyst là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển, KHÔNG lẫn với Project Manager - Quản lý dự án (quản lý tiến độ, nguồn lực) hay Dev (viết code).","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò cầu nối"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope), hỗ trợ nghiệm thu (UAT).","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 -Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Requirement, Stakeholder, Scope, UAT, BRD/SRS.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng vai trò cầu nối (15đ): Nêu rõ Business Analyst là người trung gian giữa khách hàng/doanh nghiệp và đội phát triển, KHÔNG lẫn với Project Manager - Quản lý dự án (quản lý tiến độ, nguồn lực) hay Dev (viết code).
Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: thu thập yêu cầu, phân tích nghiệp vụ, viết tài liệu đặc tả (BRD/SRS), kiểm soát phạm vi (scope), hỗ trợ nghiệm thu (UAT).
Tiêu chí 3 -Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Requirement, Stakeholder, Scope, UAT, BRD/SRS.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('95bd5a17-59d7-579c-890e-e991be19f75a', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 3, 'Bạn đã từng tham gia dự án/bài tập nào liên quan đến phân tích nghiệp vụ chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời “chưa có kinh nghiệm” chung chung - phải nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","description":"Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày có ý theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: “phải xác nhận lại yêu cầu bằng văn bản trước khi triển khai”.","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, 'Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời “chưa có kinh nghiệm” chung chung - phải nêu tên/bối cảnh dự án hoặc bài tập cụ thể, vai trò đảm nhận rõ ràng.
Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation) → Nhiệm vụ (Task) → Hành động cụ thể (Action) → Kết quả đo lường được (Result).
Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra được 1 bài học nghiệp vụ cụ thể, ví dụ: “phải xác nhận lại yêu cầu bằng văn bản trước khi triển khai”.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('43ebaf92-66c0-5d09-8282-2bec77d29091', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 4, 'Phân biệt yêu cầu chức năng (Functional) và phi chức năng (Non-functional), cho ví dụ', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Functional Requirement","description":"Tiêu chí 1 - Định nghĩa đúng Functional Requirement (15đ): Là yêu cầu mô tả HỆ THỐNG LÀM GÌ (VD: “cho phép đăng nhập bằng email”), kèm ví dụ cụ thể không chung chung.","keywords":[],"weight":15,"maxScore":15,"skill":"Định nghĩa đúng Functional Requirement"},{"id":"criterion_2","label":"Định nghĩa đúng Non-functional Requirement","description":"Tiêu chí 2 - Định nghĩa đúng Non-functional Requirement (12đ): Là yêu cầu mô tả hệ thống VẬN HÀNH TỐT ĐẾN MỨC NÀO (hiệu năng, bảo mật, khả dụng), kèm ví dụ có số liệu cụ thể (VD: “xử lý 1.000 người dùng đồng thời”).","keywords":[],"weight":12,"maxScore":12,"skill":"Định nghĩa đúng Non-functional Requirement"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Functional/Non-functional Requirement, Performance, Security, Availability.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Định nghĩa đúng Functional Requirement (15đ): Là yêu cầu mô tả HỆ THỐNG LÀM GÌ (VD: “cho phép đăng nhập bằng email”), kèm ví dụ cụ thể không chung chung.
Tiêu chí 2 - Định nghĩa đúng Non-functional Requirement (12đ): Là yêu cầu mô tả hệ thống VẬN HÀNH TỐT ĐẾN MỨC NÀO (hiệu năng, bảo mật, khả dụng), kèm ví dụ có số liệu cụ thể (VD: “xử lý 1.000 người dùng đồng thời”).
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Functional/Non-functional Requirement, Performance, Security, Availability.')
