values ('f74cf732-33ab-5029-8a09-2d6fafaa8c54', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 5, 'Bạn sẽ dùng phương pháp nào để thu thập yêu cầu từ khách hàng (phỏng vấn, workshop, khảo sát...)?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","weight":15,"maxScore":15},{"id":"criterion_2","label":"Khi nào dùng Workshop","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Khi nào dùng Phỏng vấn 1-1","description":"Tiêu chí 1 - Khi nào dùng Phỏng vấn 1-1 (15đ): Dùng khi cần đào sâu nghiệp vụ với người có chuyên môn cao, hoặc chủ đề nhạy cảm cần trao đổi riêng.","keywords":[],"weight":15,"maxScore":15,"skill":"Khi nào dùng Phỏng vấn 1-1"},{"id":"criterion_2","label":"Khi nào dùng Workshop","description":"Tiêu chí 2 - Khi nào dùng Workshop (12đ): Dùng khi có nhiều stakeholder với quan điểm khác nhau cần thống nhất trong cùng buổi họp để tiết kiệm thời gian, tránh yêu cầu mâu thuẫn.","keywords":[],"weight":12,"maxScore":12,"skill":"Khi nào dùng Workshop"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Stakeholder, Workshop, Elicitation (khai thác yêu cầu).","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Khi nào dùng Phỏng vấn 1-1 (15đ): Dùng khi cần đào sâu nghiệp vụ với người có chuyên môn cao, hoặc chủ đề nhạy cảm cần trao đổi riêng.
Tiêu chí 2 - Khi nào dùng Workshop (12đ): Dùng khi có nhiều stakeholder với quan điểm khác nhau cần thống nhất trong cùng buổi họp để tiết kiệm thời gian, tránh yêu cầu mâu thuẫn.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng các thuật ngữ Stakeholder, Workshop, Elicitation (khai thác yêu cầu).')
