values ('1bae4d3b-4f9a-5038-9df5-8b3205b3311c', (select id from public.interview_sets where slug = 'r2w-business-analyst-20261017'), 8, 'Đội Dev và khách hàng bất đồng về một yêu cầu, là Business Analyst bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Đóng vai trò trung gian dựa trên tài liệu gốc","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất giải pháp cụ thể để thống nhất","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đóng vai trò trung gian dựa trên tài liệu gốc","description":"Tiêu chí 1 - Đóng vai trò trung gian dựa trên tài liệu gốc (20đ): Đề xuất quay lại tài liệu yêu cầu đã được khách hàng ký duyệt để làm rõ ý định ban đầu, KHÔNG đứng hẳn về phía Dev hay khách hàng theo cảm tính.","keywords":[],"weight":20,"maxScore":20,"skill":"Đóng vai trò trung gian dựa trên tài liệu gốc"},{"id":"criterion_2","label":"Đề xuất giải pháp cụ thể để thống nhất","description":"Tiêu chí 2 - Đề xuất giải pháp cụ thể để thống nhất (20đ): Nêu hành động cụ thể như tổ chức họp ba bên, hoặc làm prototype/wireframe để minh hoạ trực quan giúp cả hai bên cùng hình dung.","keywords":[],"weight":20,"maxScore":20,"skill":"Đề xuất giải pháp cụ thể để thống nhất"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng các thuật ngữ Traceability, Prototype, Sign-off.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Đóng vai trò trung gian dựa trên tài liệu gốc (20đ): Đề xuất quay lại tài liệu yêu cầu đã được khách hàng ký duyệt để làm rõ ý định ban đầu, KHÔNG đứng hẳn về phía Dev hay khách hàng theo cảm tính.
Tiêu chí 2 - Đề xuất giải pháp cụ thể để thống nhất (20đ): Nêu hành động cụ thể như tổ chức họp ba bên, hoặc làm prototype/wireframe để minh hoạ trực quan giúp cả hai bên cùng hình dung.
