values ('30d7ba17-5920-5757-a580-e72553a894bc', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261017'), 1, 'Giới thiệu bản thân và lý do bạn muốn theo đuổi vị trí Credit Analyst', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng chuyên môn","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng chuyên môn","description":"Tiêu chí 1 (12đ) - Nền tảng chuyên môn: Nêu ngành học, dự án liên quan đến tài chính, ngân hàng hoặc phân tích số liệu.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng chuyên môn"},{"id":"criterion_2","label":"Lý do chọn nghề","description":"Tiêu chí 2 (10đ) - Lý do chọn nghề: Hiểu đúng vai trò Credit Analyst là phân tích khả năng trả nợ, sức khỏe tài chính và mức độ tín nhiệm của khách hàng.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (8đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (12đ) - Nền tảng chuyên môn: Nêu ngành học, dự án liên quan đến tài chính, ngân hàng hoặc phân tích số liệu.
Tiêu chí 2 (10đ) - Lý do chọn nghề: Hiểu đúng vai trò Credit Analyst là phân tích khả năng trả nợ, sức khỏe tài chính và mức độ tín nhiệm của khách hàng.
