values ('f834ec8a-1bd8-56fd-a2b8-f4e12e00f9a1', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261017'), 7, 'Khách hàng có tài sản bảo đảm tốt nhưng dòng tiền yếu, bạn có đề xuất cho vay không?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Khả năng trả nợ","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giảm thiểu rủi ro","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng và sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Khả năng trả nợ","description":"Tiêu chí 1 (20đ) - Khả năng trả nợ: Phân tích dòng tiền và nguồn trả nợ của khách hàng, không chỉ dựa vào tài sản bảo đảm để quyết định cho vay.","keywords":[],"weight":20,"maxScore":20,"skill":"Khả năng trả nợ"},{"id":"criterion_2","label":"Giảm thiểu rủi ro","description":"Tiêu chí 2 (20đ) - Giảm thiểu rủi ro: Nêu ít nhất 3/4 phương án và giải thích tác dụng:\nGiảm hạn mức\nTăng tài sản bảo đảm\nThêm điều kiện covenant\nGiám sát chặt chẽ hơn.","keywords":[],"weight":20,"maxScore":20,"skill":"Giảm thiểu rủi ro"},{"id":"criterion_3","label":"Từ vựng và sự tự tin","description":"Tiêu chí 3 (10đ) - Từ vựng và sự tự tin: Trình bày tự tin, sử dụng đúng thuật ngữ","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (20đ) - Khả năng trả nợ: Phân tích dòng tiền và nguồn trả nợ của khách hàng, không chỉ dựa vào tài sản bảo đảm để quyết định cho vay.
Tiêu chí 2 (20đ) - Giảm thiểu rủi ro: Nêu ít nhất 3/4 phương án và giải thích tác dụng:
Giảm hạn mức
