insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('77fa815a-dd47-5c37-a2a9-62ca66aa5854', (select id from public.interview_sets where slug = 'r2w-credit-analyst-20261017'), 8, 'Cấp trên yêu cầu bạn nhanh chóng phê duyệt một khoản vay lớn nhưng hồ sơ tài chính còn thiếu thông tin. Bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Làm rõ TH","weight":15,"maxScore":15},{"id":"criterion_2","label":"Tuân thủ nguyên tắc tín dụng","weight":15,"maxScore":15},{"id":"criterion_3","label":"Giải pháp xử lý","weight":15,"maxScore":15},{"id":"criterion_4","label":"Từ vựng và sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Làm rõ TH","description":"Tiêu chí 1 (15đ) - Làm rõ TH:\nXác định lý do khẩn cấp, thời hạn và thông tin còn thiếu\nPhản ứng đồng ý hay từ chối ngay (0đ)","keywords":[],"weight":15,"maxScore":15,"skill":"Làm rõ TH"},{"id":"criterion_2","label":"Tuân thủ nguyên tắc tín dụng","description":"Tiêu chí 2 (15đ) - Tuân thủ nguyên tắc tín dụng: Không bỏ qua thẩm định thiết yếu; đảm bảo kiểm soát chéo, đúng quy trình và trách nhiệm cá nhân.","keywords":[],"weight":15,"maxScore":15,"skill":"Tuân thủ nguyên tắc tín dụng"},{"id":"criterion_3","label":"Giải pháp xử lý","description":"Tiêu chí 3 (15đ) - Giải pháp xử lý: Nêu ít nhất 2/3 giải pháp: bổ sung nhanh thông tin, phê duyệt có điều kiện, giảm hạn mức hoặc giải ngân từng đợt.","keywords":[],"weight":15,"maxScore":15,"skill":"Giải pháp xử lý"},{"id":"criterion_4","label":"Từ vựng và sự tự tin","description":"Tiêu chí 4 (5đ) - Từ vựng và sự tự tin: Trình bày rõ ràng, sử dụng đúng thuật ngữ","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng và sự tự tin"}]'::jsonb, 'Tiêu chí 1 (15đ) - Làm rõ TH:
Xác định lý do khẩn cấp, thời hạn và thông tin còn thiếu
Phản ứng đồng ý hay từ chối ngay (0đ)
Tiêu chí 2 (15đ) - Tuân thủ nguyên tắc tín dụng: Không bỏ qua thẩm định thiết yếu; đảm bảo kiểm soát chéo, đúng quy trình và trách nhiệm cá nhân.
