values ('c356131b-8bfd-53d6-92b5-a788c9c73343', (select id from public.interview_sets where slug = 'r2w-data-analyst-20261017'), 6, 'Hãy chỉ ra cách xử lý dữ liệu missing/outlier trong tập dữ liệu', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Đề xuất đúng theo tỉ lệ dữ liệu thiếu","weight":18,"maxScore":18},{"id":"criterion_2","label":"Nêu đúng phương pháp phát hiện outlier","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Đề xuất đúng theo tỉ lệ dữ liệu thiếu","description":"Tiêu chí 1 - Đề xuất đúng theo tỉ lệ dữ liệu thiếu (18đ): Tỉ lệ thiếu lớn → cân nhắc loại bỏ; tỷ lệ thiếu nhỏ và dữ liệu quan trọng → điền giá trị thay thế (mean/median/mode).","keywords":[],"weight":18,"maxScore":18,"skill":"Đề xuất đúng theo tỉ lệ dữ liệu thiếu"},{"id":"criterion_2","label":"Nêu đúng phương pháp phát hiện outlier","description":"Tiêu chí 2 - Nêu đúng phương pháp phát hiện outlier (10đ): Dùng Boxplot hoặc IQR (Interquartile Range) để phát hiện, và cân nhắc bối cảnh nghiệp vụ trước khi loại bỏ.","keywords":[],"weight":10,"maxScore":10,"skill":"Nêu đúng phương pháp phát hiện outlier"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng các thuật ngữ Missing Data, Outlier, IQR, Mean/Median/Mode.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Đề xuất đúng theo tỉ lệ dữ liệu thiếu (18đ): Tỉ lệ thiếu lớn → cân nhắc loại bỏ; tỷ lệ thiếu nhỏ và dữ liệu quan trọng → điền giá trị thay thế (mean/median/mode).
