values ('d9b71b7d-4b66-5898-9ed7-9756b315cbff', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261017'), 1, 'Hãy giới thiệu ngắn gọn về bản thân và lý do bạn lựa chọn công việc kế toán?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","weight":10,"maxScore":10},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Giới thiệu đúng thông tin cá nhân","description":"Tiêu chí 1- Giới thiệu đúng thông tin cá nhân  (12đ): Nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán.","keywords":[],"weight":12,"maxScore":12,"skill":"Giới thiệu đúng thông tin cá nhân"},{"id":"criterion_2","label":"Lý do chọn nghề đúng bản chất","description":"Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Nêu được lý do cụ thể như yêu thích số liệu, quan tâm đến tài chính - kế toán hoặc muốn phát triển chuyên môn.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do chọn nghề đúng bản chất"},{"id":"criterion_3","label":"Liên hệ điểm mạnh với công việc","description":"Tiêu chí 3 - Liên hệ điểm mạnh với công việc (8đ): Nêu tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm và giải thích được sự phù hợp.","keywords":[],"weight":8,"maxScore":8,"skill":"Liên hệ điểm mạnh với công việc"}]'::jsonb, 'Tiêu chí 1- Giới thiệu đúng thông tin cá nhân  (12đ): Nêu được ngành học, kinh nghiệm/thực tập hoặc hoạt động liên quan đến kế toán.
Tiêu chí 2 - Lý do chọn nghề đúng bản chất (10đ): Nêu được lý do cụ thể như yêu thích số liệu, quan tâm đến tài chính - kế toán hoặc muốn phát triển chuyên môn.
Tiêu chí 3 - Liên hệ điểm mạnh với công việc (8đ): Nêu tối thiểu 2 điểm mạnh phù hợp như cẩn thận, chính xác, trung thực, trách nhiệm và giải thích được sự phù hợp.')
