values ('50bb5cab-5222-56e6-88f7-22afee2b3588', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261017'), 2, 'Theo bạn, một kế toán viên cần có những kỹ năng quan trọng nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Chính xác và cẩn thận","weight":15,"maxScore":15},{"id":"criterion_2","label":"Kiến thức chuyên môn","weight":12,"maxScore":12},{"id":"criterion_3","label":"Trung thực và trách nhiệm","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Chính xác và cẩn thận","description":"Tiêu chí 1 - Chính xác và cẩn thận (15đ): Hiểu rằng kế toán thường xuyên làm việc với số liệu, hóa đơn và chứng từ nên cần hạn chế sai sót.","keywords":[],"weight":15,"maxScore":15,"skill":"Chính xác và cẩn thận"},{"id":"criterion_2","label":"Kiến thức chuyên môn","description":"Tiêu chí 2 - Kiến thức chuyên môn (12đ): Đề cập được hạch toán, chứng từ, sổ sách, doanh thu - chi phí hoặc nghiệp vụ kế toán cơ bản.","keywords":[],"weight":12,"maxScore":12,"skill":"Kiến thức chuyên môn"},{"id":"criterion_3","label":"Trung thực và trách nhiệm","description":"Tiêu chí 3 - Trung thực và trách nhiệm (8đ): Hiểu trách nhiệm của kế toán đối với số liệu và không cố tình làm sai lệch thông tin.","keywords":[],"weight":8,"maxScore":8,"skill":"Trung thực và trách nhiệm"}]'::jsonb, 'Tiêu chí 1 - Chính xác và cẩn thận (15đ): Hiểu rằng kế toán thường xuyên làm việc với số liệu, hóa đơn và chứng từ nên cần hạn chế sai sót.
Tiêu chí 2 - Kiến thức chuyên môn (12đ): Đề cập được hạch toán, chứng từ, sổ sách, doanh thu - chi phí hoặc nghiệp vụ kế toán cơ bản.
Tiêu chí 3 - Trung thực và trách nhiệm (8đ): Hiểu trách nhiệm của kế toán đối với số liệu và không cố tình làm sai lệch thông tin.')
