values ('6b91b186-f912-5118-9687-7dac1a12b443', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261017'), 7, 'Cuối ngày, bạn phát hiện một chứng từ quan trọng có sai sót nhưng quản lý đang yêu cầu hoàn thành báo cáo gấp. Bạn sẽ xử lý như thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Trung thực, không che giấu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Ưu tiên công việc","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Trung thực, không che giấu","description":"Tiêu chí 1 - Trung thực, không che giấu (20đ): Thông báo về sai sót, không bỏ qua hoặc cố tình sửa số liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Trung thực, không che giấu"},{"id":"criterion_2","label":"Đánh giá mức độ ảnh hưởng","description":"Tiêu chí 2 - Đánh giá mức độ ảnh hưởng (20đ): Xác định chứng từ ảnh hưởng đến phần nào của báo cáo.","keywords":[],"weight":20,"maxScore":20,"skill":"Đánh giá mức độ ảnh hưởng"},{"id":"criterion_3","label":"Ưu tiên công việc","description":"Tiêu chí 3 - Ưu tiên công việc (10đ): Có thể hoàn thành phần báo cáo không bị ảnh hưởng trong khi xử lý sai sót.","keywords":[],"weight":10,"maxScore":10,"skill":"Ưu tiên công việc"}]'::jsonb, 'Tiêu chí 1 - Trung thực, không che giấu (20đ): Thông báo về sai sót, không bỏ qua hoặc cố tình sửa số liệu.
Tiêu chí 2 - Đánh giá mức độ ảnh hưởng (20đ): Xác định chứng từ ảnh hưởng đến phần nào của báo cáo.
Tiêu chí 3 - Ưu tiên công việc (10đ): Có thể hoàn thành phần báo cáo không bị ảnh hưởng trong khi xử lý sai sót.')
