values ('107f1ddd-99d6-5122-896c-2aec8eda3e2f', (select id from public.interview_sets where slug = 'r2w-ke-toan-vien-20261017'), 8, 'Nếu đồng nghiệp đề nghị bạn bỏ qua một sai sót nhỏ trong chứng từ để kịp thời hạn báo cáo, bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Nhận diện rủi ro","weight":20,"maxScore":20},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tính trung thực","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Nhận diện rủi ro","description":"Tiêu chí 1 - Nhận diện rủi ro (20đ): Hiểu rằng sai sót nhỏ vẫn có thể gây ảnh hưởng nếu không được xử lý.","keywords":[],"weight":20,"maxScore":20,"skill":"Nhận diện rủi ro"},{"id":"criterion_2","label":"Trao đổi với đồng nghiệp","description":"Tiêu chí 2 - Trao đổi với đồng nghiệp (20đ): Giải thích lý do cần xử lý thay vì bỏ qua","keywords":[],"weight":20,"maxScore":20,"skill":"Trao đổi với đồng nghiệp"},{"id":"criterion_3","label":"Tính trung thực","description":"Tiêu chí 3 - Tính trung thực (10đ): Đặt tính chính xác và trung thực của số liệu lên trên việc đối phó với deadline.","keywords":[],"weight":10,"maxScore":10,"skill":"Tính trung thực"}]'::jsonb, 'Tiêu chí 1 - Nhận diện rủi ro (20đ): Hiểu rằng sai sót nhỏ vẫn có thể gây ảnh hưởng nếu không được xử lý.
Tiêu chí 2 - Trao đổi với đồng nghiệp (20đ): Giải thích lý do cần xử lý thay vì bỏ qua
Tiêu chí 3 - Tính trung thực (10đ): Đặt tính chính xác và trung thực của số liệu lên trên việc đối phó với deadline.')
