values ('5d232f1a-315f-5008-a4d5-518dee05620b', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261017'), 7, 'Nếu khách hàng không cung cấp đầy đủ bằng chứng kiểm toán, bạn sẽ xử lý như thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Xác định bằng chứng thiếu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Yêu cầu khách hàng bổ sung","weight":20,"maxScore":20},{"id":"criterion_3","label":"Tìm bằng chứng thay thế","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác định bằng chứng thiếu","description":"Tiêu chí 1 - Xác định bằng chứng thiếu (20đ): Xác định tài liệu nào chưa được cung cấp và liên quan khoản mục nào.","keywords":[],"weight":20,"maxScore":20,"skill":"Xác định bằng chứng thiếu"},{"id":"criterion_2","label":"Yêu cầu khách hàng bổ sung","description":"Tiêu chí 2 - Yêu cầu khách hàng bổ sung (20đ): Chủ động liên hệ và nêu rõ tài liệu cần cung cấp.","keywords":[],"weight":20,"maxScore":20,"skill":"Yêu cầu khách hàng bổ sung"},{"id":"criterion_3","label":"Tìm bằng chứng thay thế","description":"Tiêu chí 3 - Tìm bằng chứng thay thế (10đ): Có thể tìm xác nhận bên ngoài, chứng từ ngân hàng hoặc hồ sơ liên quan.","keywords":[],"weight":10,"maxScore":10,"skill":"Tìm bằng chứng thay thế"}]'::jsonb, 'Tiêu chí 1 - Xác định bằng chứng thiếu (20đ): Xác định tài liệu nào chưa được cung cấp và liên quan khoản mục nào.
Tiêu chí 2 - Yêu cầu khách hàng bổ sung (20đ): Chủ động liên hệ và nêu rõ tài liệu cần cung cấp.
Tiêu chí 3 - Tìm bằng chứng thay thế (10đ): Có thể tìm xác nhận bên ngoài, chứng từ ngân hàng hoặc hồ sơ liên quan.')
