values ('9d96bad0-bd23-5f38-aafc-9bedca6f5b6c', (select id from public.interview_sets where slug = 'r2w-kiem-toan-vien-20261017'), 8, 'Khách hàng đưa ra lời giải thích nhưng bằng chứng không hoàn toàn phù hợp với lời giải thích đó. Bạn sẽ làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Đánh giá rủi ro","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Không chấp nhận ngay lời giải thích","description":"Tiêu chí 1 - Không chấp nhận ngay lời giải thích (20đ): Hiểu rằng lời giải thích bằng miệng không thay thế hoàn toàn bằng chứng kiểm toán.","keywords":[],"weight":20,"maxScore":20,"skill":"Không chấp nhận ngay lời giải thích"},{"id":"criterion_2","label":"Kiểm tra thêm bằng chứng","description":"Tiêu chí 2 - Kiểm tra thêm bằng chứng (20đ): Đối chiếu hợp đồng, hóa đơn, thanh toán, giao nhận hoặc nguồn độc lập","keywords":[],"weight":20,"maxScore":20,"skill":"Kiểm tra thêm bằng chứng"},{"id":"criterion_3","label":"Đánh giá rủi ro","description":"Tiêu chí 3 - Đánh giá rủi ro (10đ): Xem xét có dấu hiệu sai sót hoặc gian lận hay không.","keywords":[],"weight":10,"maxScore":10,"skill":"Đánh giá rủi ro"}]'::jsonb, 'Tiêu chí 1 - Không chấp nhận ngay lời giải thích (20đ): Hiểu rằng lời giải thích bằng miệng không thay thế hoàn toàn bằng chứng kiểm toán.
