values ('de8fae06-3f7f-5c08-9d3a-45edca11870a', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 1, 'Giới thiệu bản thân và vì sao bạn chọn theo đuổi vị trí Chuyên viên Vận hành Logistics?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể ngành học/dự án/kinh nghiệm làm việc thực tế liên quan trực tiếp đến giao nhận, điều phối vận tải, quản lý kho bãi hoặc xử lý chứng từ logistics.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù công việc Logistics Operations là theo dõi đơn hàng, điều phối hiện trường, xử lý sự cố phát sinh và quản lý luồng hàng; không nhầm với Nhân viên Kinh doanh cước (Sales Logistics) hay Thu mua.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ cơ bản: SLA, Lead Time, POD, Inbound/Outbound, Carrier","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể ngành học/dự án/kinh nghiệm làm việc thực tế liên quan trực tiếp đến giao nhận, điều phối vận tải, quản lý kho bãi hoặc xử lý chứng từ logistics.
Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù công việc Logistics Operations là theo dõi đơn hàng, điều phối hiện trường, xử lý sự cố phát sinh và quản lý luồng hàng; không nhầm với Nhân viên Kinh doanh cước (Sales Logistics) hay Thu mua.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ cơ bản: SLA, Lead Time, POD, Inbound/Outbound, Carrier')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
