  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('bae5c61a-8d28-53f5-aa2f-127009683cae', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 2, 'Bạn hiểu vai trò của một Chuyên viên Vận hành Logistics trong doanh nghiệp là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là cầu nối trung tâm giữa Kho - Nhà vận chuyển - Tài xế - Khách hàng để đảm bảo hàng hóa luân chuyển đúng tiến độ, an toàn và đúng quy trình SOP.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: Theo dõi trạng thái đơn hàng, kiểm tra/lưu trữ chứng từ (Bill/POD), điều phối xe bốc xếp, xử lý ngoại lệ (trễ/hỏng xe), theo dõi chi phí & hiệu suất.","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SOP, 3PL, Exception Handling, Dispatch, Tracking.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là cầu nối trung tâm giữa Kho - Nhà vận chuyển - Tài xế - Khách hàng để đảm bảo hàng hóa luân chuyển đúng tiến độ, an toàn và đúng quy trình SOP.
Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 đầu việc: Theo dõi trạng thái đơn hàng, kiểm tra/lưu trữ chứng từ (Bill/POD), điều phối xe bốc xếp, xử lý ngoại lệ (trễ/hỏng xe), theo dõi chi phí & hiệu suất.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SOP, 3PL, Exception Handling, Dispatch, Tracking.')
on conflict (set_id, position) do update set
