insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('474853ab-dd91-57e3-b65f-eb74268bd208', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 3, 'Bạn đã từng tham gia bài tập/dự án hoặc trải nghiệm thực tế nào liên quan đến điều phối và vận hành hàng hóa chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời \"chưa có kinh nghiệm\" chung chung — nêu tên/bối cảnh bài tập mô phỏng, dự án sinh viên hoặc đợt thực tập cụ thể, vai trò đảm nhận rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày có ý theo cấu trúc STAR","description":"Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động cụ thể (Action)  Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày có ý theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học nghiệp vụ thực tế, ví dụ: \"phải kiểm tra chéo chứng từ trước khi xuất kho và luôn nhận phản hồi xác nhận từ tài xế\".","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, 'Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Không trả lời "chưa có kinh nghiệm" chung chung — nêu tên/bối cảnh bài tập mô phỏng, dự án sinh viên hoặc đợt thực tập cụ thể, vai trò đảm nhận rõ ràng.
Tiêu chí 2 - Trình bày có ý theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động cụ thể (Action)  Kết quả đo lường được (Result).
Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học nghiệp vụ thực tế, ví dụ: "phải kiểm tra chéo chứng từ trước khi xuất kho và luôn nhận phản hồi xác nhận từ tài xế".')
