insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c96a80ad-d15f-5328-ae56-47ac7c5db585', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 4, 'Trình bày các bước trong quy trình vận hành đơn hàng (Order Fulfillment Cycle) từ khi nhận yêu cầu đến khi hoàn tất giao hàng?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Liệt kê đúng trình tự các bước","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải thích điểm kiểm soát SOP","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng trình tự các bước","description":"Tiêu chí 1 - Liệt kê đúng trình tự các bước (15đ): Tiếp nhận yêu cầu  Kiểm tra tồn kho & chứng từ  Điều phối kho/xe bốc xếp  Theo dõi hành trình  Xác nhận giao hàng (POD).","keywords":[],"weight":15,"maxScore":15,"skill":"Liệt kê đúng trình tự các bước"},{"id":"criterion_2","label":"Giải thích điểm kiểm soát SOP","description":"Tiêu chí 2 - Giải thích điểm kiểm soát SOP (12đ): Nêu rõ nguyên tắc không xuất hàng khi lệch chứng từ và chỉ đánh dấu hoàn tất khi nhận được bằng chứng giao hàng (POD).","keywords":[],"weight":12,"maxScore":12,"skill":"Giải thích điểm kiểm soát SOP"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Order Processing, Dispatch, Cross-docking, Proof of Delivery (POD).","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đúng trình tự các bước (15đ): Tiếp nhận yêu cầu  Kiểm tra tồn kho & chứng từ  Điều phối kho/xe bốc xếp  Theo dõi hành trình  Xác nhận giao hàng (POD).
Tiêu chí 2 - Giải thích điểm kiểm soát SOP (12đ): Nêu rõ nguyên tắc không xuất hàng khi lệch chứng từ và chỉ đánh dấu hoàn tất khi nhận được bằng chứng giao hàng (POD).
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Order Processing, Dispatch, Cross-docking, Proof of Delivery (POD).')
