values ('d94dd406-935e-5219-a9e5-5751a0a1f8c3', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 5, 'Khi nào nên chọn điều kiện giao hàng Incoterms FOB và CIF trong xuất nhập khẩu hàng hóa?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Lựa chọn đúng theo bản chất","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích chuyển giao rủi ro & chi phí","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Lựa chọn đúng theo bản chất","description":"Tiêu chí 1 - Lựa chọn đúng theo bản chất (18đ): Bán CIF cho hàng xuất nông sản/giá trị thấp để chủ động cước tàu & chuỗi lạnh; Mua FOB cho hàng nhập điện tử/giá trị cao để tự chủ bảo hiểm và chỉ định nhà vận chuyển uy tín tại Việt Nam.","keywords":[],"weight":18,"maxScore":18,"skill":"Lựa chọn đúng theo bản chất"},{"id":"criterion_2","label":"Giải thích chuyển giao rủi ro & chi phí","description":"Tiêu chí 2 - Giải thích chuyển giao rủi ro & chi phí (10đ): Giải thích đúng điểm chuyển giao rủi ro hàng hóa và nghĩa vụ trả cước tàu/bảo hiểm theo Incoterms 2020.","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích chuyển giao rủi ro & chi phí"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Freight, Insurance, Port of Loading, Port of Discharge, Risk Transfer.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Lựa chọn đúng theo bản chất (18đ): Bán CIF cho hàng xuất nông sản/giá trị thấp để chủ động cước tàu & chuỗi lạnh; Mua FOB cho hàng nhập điện tử/giá trị cao để tự chủ bảo hiểm và chỉ định nhà vận chuyển uy tín tại Việt Nam.
Tiêu chí 2 - Giải thích chuyển giao rủi ro & chi phí (10đ): Giải thích đúng điểm chuyển giao rủi ro hàng hóa và nghĩa vụ trả cước tàu/bảo hiểm theo Incoterms 2020.
