values ('97c41847-2fbb-53e8-bc4c-9f69be8b3ef5', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 6, 'Bạn làm thế nào để kiểm soát chi phí vận hành và rủi ro trễ hạn cam kết giao hàng (SLA)?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Biện pháp kiểm soát SLA","weight":15,"maxScore":15},{"id":"criterion_2","label":"Tuân thủ thẩm quyền chi phí","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Biện pháp kiểm soát SLA","description":"Tiêu chí 1 - Biện pháp kiểm soát SLA (15đ): Thiết lập đệm thời gian (Buffer time), theo dõi vị trí xe định kỳ và giám sát mốc thời gian bốc xếp tại kho.","keywords":[],"weight":15,"maxScore":15,"skill":"Biện pháp kiểm soát SLA"},{"id":"criterion_2","label":"Tuân thủ thẩm quyền chi phí","description":"Tiêu chí 2 - Tuân thủ thẩm quyền chi phí (12đ): Nhấn mạnh nguyên tắc không tự ý xác nhận các khoản phụ phí phát sinh vượt ngưỡng quy định (VD: > 200.000đ) khi chưa được Quản lý phê duyệt.","keywords":[],"weight":12,"maxScore":12,"skill":"Tuân thủ thẩm quyền chi phí"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: SLA Margin, Buffer Time, Surcharge, Escalation, Cost Control.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Biện pháp kiểm soát SLA (15đ): Thiết lập đệm thời gian (Buffer time), theo dõi vị trí xe định kỳ và giám sát mốc thời gian bốc xếp tại kho.
Tiêu chí 2 - Tuân thủ thẩm quyền chi phí (12đ): Nhấn mạnh nguyên tắc không tự ý xác nhận các khoản phụ phí phát sinh vượt ngưỡng quy định (VD: > 200.000đ) khi chưa được Quản lý phê duyệt.
