insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('4136387b-c552-5a0b-a0b9-8937d3168181', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 7, 'Nhân viên kho báo Phiếu giao hàng ghi 30 thùng nhưng Đơn hàng (PO) ghi 32 thùng, xe chở hàng đang chờ rời kho, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Xác minh & Tuân thủ SOP","weight":20,"maxScore":20},{"id":"criterion_2","label":"Xử lý chứng từ & Thông báo","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Xác minh & Tuân thủ SOP","description":"Tiêu chí 1 - Xác minh & Tuân thủ SOP (20đ): Lập tức ra lệnh tạm dừng xuất hàng; không tự ý sửa số liệu; yêu cầu Kho kiểm đếm thực tế và đối chiếu PO/Biên bản.","keywords":[],"weight":20,"maxScore":20,"skill":"Xác minh & Tuân thủ SOP"},{"id":"criterion_2","label":"Xử lý chứng từ & Thông báo","description":"Tiêu chí 2 - Xử lý chứng từ & Thông báo (20đ): Yêu cầu in lại phiếu giao đúng số lượng thực xuất trước khi cho xe rời kho; cập nhật thông tin minh bạch cho các bên liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Xử lý chứng từ & Thông báo"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Document Discrepancy, Hold Shipment, PO Reconciliation, Packing List.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác minh & Tuân thủ SOP (20đ): Lập tức ra lệnh tạm dừng xuất hàng; không tự ý sửa số liệu; yêu cầu Kho kiểm đếm thực tế và đối chiếu PO/Biên bản.
Tiêu chí 2 - Xử lý chứng từ & Thông báo (20đ): Yêu cầu in lại phiếu giao đúng số lượng thực xuất trước khi cho xe rời kho; cập nhật thông tin minh bạch cho các bên liên quan.
