insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('7cee57c4-1021-58d4-9ef7-d3daa17ca341', (select id from public.interview_sets where slug = 'r2w-logistics-ops-20261017'), 8, 'Xe chở hàng gặp sự cố hỏng trên đường có nguy cơ trễ SLA 1 tiếng. Xe thay thế ngoài có thể giao đúng hạn nhưng phát sinh phụ phí 350.000đ (vượt hạn mức tự duyệt 200.000đ), bạn làm gì?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Tuân thủ thẩm quyền & Khẩn cấp","weight":20,"maxScore":20},{"id":"criterion_2","label":"Phương án dự phòng","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Tuân thủ thẩm quyền & Khẩn cấp","description":"Tiêu chí 1 - Tuân thủ thẩm quyền & Khẩn cấp (20đ): Liên hệ Quản lý ngay lập tức để trình duyệt khoản phụ phí 350.000đ trước hạn báo giá của nhà xe (VD: trước 09:35) để đảm bảo SLA.","keywords":[],"weight":20,"maxScore":20,"skill":"Tuân thủ thẩm quyền & Khẩn cấp"},{"id":"criterion_2","label":"Phương án dự phòng","description":"Tiêu chí 2 - Phương án dự phòng (20đ): Nếu Quản lý không duyệt chi phí, chủ động liên hệ ngay với Khách hàng để thông báo rủi ro trễ tiến độ và xin gia hạn thời gian giao.","keywords":[],"weight":20,"maxScore":20,"skill":"Phương án dự phòng"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Escalation, Emergency Transport, SLA Violation, Contingency Plan.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Tuân thủ thẩm quyền & Khẩn cấp (20đ): Liên hệ Quản lý ngay lập tức để trình duyệt khoản phụ phí 350.000đ trước hạn báo giá của nhà xe (VD: trước 09:35) để đảm bảo SLA.
Tiêu chí 2 - Phương án dự phòng (20đ): Nếu Quản lý không duyệt chi phí, chủ động liên hệ ngay với Khách hàng để thông báo rủi ro trễ tiến độ và xin gia hạn thời gian giao.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Escalation, Emergency Transport, SLA Violation, Contingency Plan.')
