insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('0b21445f-f881-594a-b879-6b0c6f8cb8e9', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 1, 'Giới thiệu bản thân và vì sao bạn chọn theo đuổi nghề Thu mua (Purchasing/Procurement)?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án/kinh nghiệm thực tế liên quan đến thương mại, đàm phán báo giá, đánh giá nhà cung cấp hoặc quản lý hợp đồng.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù nghề Thu mua là tối ưu tổng chi phí (Landed Cost), quản lý rủi ro nhà cung cấp và đảm bảo nguồn cung đúng SLA; không nhầm với Sales hay Kế toán.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Procurement, Landed Cost, Vendor Management, PO, PR.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án/kinh nghiệm thực tế liên quan đến thương mại, đàm phán báo giá, đánh giá nhà cung cấp hoặc quản lý hợp đồng.
Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đúng đặc thù nghề Thu mua là tối ưu tổng chi phí (Landed Cost), quản lý rủi ro nhà cung cấp và đảm bảo nguồn cung đúng SLA; không nhầm với Sales hay Kế toán.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Procurement, Landed Cost, Vendor Management, PO, PR.')
