insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('a5a5eca4-3929-5ec6-8776-3cd121da8327', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 2, 'Bạn hiểu vai trò của Chuyên viên Thu mua trong doanh nghiệp là gì và làm sao để đảm bảo tính minh bạch, chống rủi ro "bắt tay ngầm" (Kickback)?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Biện pháp chống rủi ro minh bạch","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Tiêu chí 1 - Xác định đúng vai trò (15đ): Đầu mối tìm kiếm, đàm phán điều khoản thương mại và quản lý luồng PR-PO đảm bảo mua đúng chất lượng, đúng giá và đúng thời điểm.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Biện pháp chống rủi ro minh bạch","description":"Tiêu chí 2 - Biện pháp chống rủi ro minh bạch (12đ): Tuân thủ quy trình 3-Quote (tối thiểu 3 báo giá độc lập); phân tách vai trò (Thu mua tìm giá, QA/QC test hàng mẫu); dùng bảng Vendor Scorecard trình Sếp duyệt.","keywords":[],"weight":12,"maxScore":12,"skill":"Biện pháp chống rủi ro minh bạch"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: 3-Quote, RFQ, Vendor Scorecard, Anti-Kickback, Transparency.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng vai trò (15đ): Đầu mối tìm kiếm, đàm phán điều khoản thương mại và quản lý luồng PR-PO đảm bảo mua đúng chất lượng, đúng giá và đúng thời điểm.
Tiêu chí 2 - Biện pháp chống rủi ro minh bạch (12đ): Tuân thủ quy trình 3-Quote (tối thiểu 3 báo giá độc lập); phân tách vai trò (Thu mua tìm giá, QA/QC test hàng mẫu); dùng bảng Vendor Scorecard trình Sếp duyệt.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: 3-Quote, RFQ, Vendor Scorecard, Anti-Kickback, Transparency.')
