values ('f0ab1a3a-b61a-51bb-8bd7-5a85411af269', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 3, 'Bạn đã từng tham gia bài tập/dự án nào liên quan đến tìm kiếm hoặc đàm phán với nhà cung cấp chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Rút ra bài học cụ thể","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên dự án/bài tập cụ thể (Sourcing bao bì, đàm phán báo giá vật tư, thay thế NCC kém chất lượng...), mô tả vai trò rõ ràng.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","description":"Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động đàm phán/sourcing (Action)  Kết quả tiết kiệm chi phí/đảm bảo tiến độ (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày theo cấu trúc STAR"},{"id":"criterion_3","label":"Rút ra bài học cụ thể","description":"Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học thực tế, ví dụ: \"phải so sánh Tổng chi phí thực tế (Landed Cost) chứ không chỉ nhìn vào đơn giá rẻ nhất\".","keywords":[],"weight":8,"maxScore":8,"skill":"Rút ra bài học cụ thể"}]'::jsonb, 'Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên dự án/bài tập cụ thể (Sourcing bao bì, đàm phán báo giá vật tư, thay thế NCC kém chất lượng...), mô tả vai trò rõ ràng.
Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động đàm phán/sourcing (Action)  Kết quả tiết kiệm chi phí/đảm bảo tiến độ (Result).
Tiêu chí 3 - Rút ra bài học cụ thể (8đ): Chỉ ra 1 bài học thực tế, ví dụ: "phải so sánh Tổng chi phí thực tế (Landed Cost) chứ không chỉ nhìn vào đơn giá rẻ nhất".')
