insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('7e96dc84-7efd-5495-9428-33d477a8344f', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 4, 'Trình bày quy trình Sourcing nhà cung cấp mới từ khi nhận Yêu cầu mua hàng (PR) đến khi hoàn tất ký hợp đồng/PO?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Liệt kê đủ các bước chuẩn","weight":15,"maxScore":15},{"id":"criterion_2","label":"Nắm vững quy định SOP","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các bước chuẩn","description":"Tiêu chí 1 - Liệt kê đủ các bước chuẩn (15đ): Tiếp nhận PR  Tìm nguồn cung  Gửi RFQ cho  bên  Bảng so sánh giá (Cost Matrix)  Test mẫu (Sample Audit)  Đàm phán  Trình duyệt & Ký PO/Hợp đồng.","keywords":[],"weight":15,"maxScore":15,"skill":"Liệt kê đủ các bước chuẩn"},{"id":"criterion_2","label":"Nắm vững quy định SOP","description":"Tiêu chí 2 - Nắm vững quy định SOP (12đ): Nhấn mạnh mọi đơn hàng trên hạn mức (VD: > 100 triệu) bắt buộc phải lập Tờ trình xin ý kiến Trưởng phòng phê duyệt trước khi phát hành PO.","keywords":[],"weight":12,"maxScore":12,"skill":"Nắm vững quy định SOP"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: PR, PO, RFQ, Cost Comparison Matrix, Sample Audit, Contract.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đủ các bước chuẩn (15đ): Tiếp nhận PR  Tìm nguồn cung  Gửi RFQ cho  bên  Bảng so sánh giá (Cost Matrix)  Test mẫu (Sample Audit)  Đàm phán  Trình duyệt & Ký PO/Hợp đồng.
Tiêu chí 2 - Nắm vững quy định SOP (12đ): Nhấn mạnh mọi đơn hàng trên hạn mức (VD: > 100 triệu) bắt buộc phải lập Tờ trình xin ý kiến Trưởng phòng phê duyệt trước khi phát hành PO.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: PR, PO, RFQ, Cost Comparison Matrix, Sample Audit, Contract.')
