insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3157fc84-d51d-5d15-8c3a-0f0fc13cb100', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 5, 'Khái niệm Tổng chi phí thực tế (Landed Cost) là gì và làm thế nào để lựa chọn giữa các báo giá có điều kiện khác nhau?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Nêu đúng công thức Landed Cost","weight":18,"maxScore":18},{"id":"criterion_2","label":"Phân tích Đánh đổi Thương mại","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nêu đúng công thức Landed Cost","description":"Tiêu chí 1 - Nêu đúng công thức Landed Cost (18đ): Landed Cost = Đơn giá có VAT + Vận chuyển/Bảo hiểm + Lưu kho/Thủ tục phát sinh","keywords":[],"weight":18,"maxScore":18,"skill":"Nêu đúng công thức Landed Cost"},{"id":"criterion_2","label":"Phân tích Đánh đổi Thương mại","description":"Tiêu chí 2 - Phân tích Đánh đổi Thương mại (10đ): Lựa chọn NCC có Landed Cost hợp lý, đáp ứng SLA và cho trả chậm 30 ngày (tối ưu dòng tiền) hơn là chọn NCC giá rẻ nhưng bắt trả trước 100% hoặc trễ SLA.","keywords":[],"weight":10,"maxScore":10,"skill":"Phân tích Đánh đổi Thương mại"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Landed Cost, VAT, Working Capital, Trade-off, Payment Terms.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Nêu đúng công thức Landed Cost (18đ): Landed Cost = Đơn giá có VAT + Vận chuyển/Bảo hiểm + Lưu kho/Thủ tục phát sinh
Tiêu chí 2 - Phân tích Đánh đổi Thương mại (10đ): Lựa chọn NCC có Landed Cost hợp lý, đáp ứng SLA và cho trả chậm 30 ngày (tối ưu dòng tiền) hơn là chọn NCC giá rẻ nhưng bắt trả trước 100% hoặc trễ SLA.
Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Landed Cost, VAT, Working Capital, Trade-off, Payment Terms.')
