insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('1ed59abb-a4b5-54b2-a00e-7a92298ba7a4', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 6, 'Khi nhà cung cấp giao lô hàng bị lỗi kỹ thuật 20%, bạn phối hợp xử lý như thế nào để đảm bảo không gián đoạn sản xuất?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Lập biên bản & Căn cứ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Đề xuất phương án kiên quyết","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Lập biên bản & Căn cứ","description":"Tiêu chí 1 - Lập biên bản & Căn cứ (15đ): Yêu cầu biên bản kiểm hàng từ Kho/QA-QC; gửi thư khiếu nại chính thức cho NCC kèm số liệu sản phẩm lỗi cụ thể.","keywords":[],"weight":15,"maxScore":15,"skill":"Lập biên bản & Căn cứ"},{"id":"criterion_2","label":"Đề xuất phương án kiên quyết","description":"Tiêu chí 2 - Đề xuất phương án kiên quyết (12đ): Yêu cầu NCC đổi bù đủ hàng đạt chuẩn trong 48h HOẶC cấn trừ giá trị hàng lỗi trực tiếp vào công nợ đơn sau.","keywords":[],"weight":12,"maxScore":12,"skill":"Đề xuất phương án kiên quyết"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Defect Rate, Quality Claim, Debit Note, Replacement, SOP.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Lập biên bản & Căn cứ (15đ): Yêu cầu biên bản kiểm hàng từ Kho/QA-QC; gửi thư khiếu nại chính thức cho NCC kèm số liệu sản phẩm lỗi cụ thể.
Tiêu chí 2 - Đề xuất phương án kiên quyết (12đ): Yêu cầu NCC đổi bù đủ hàng đạt chuẩn trong 48h HOẶC cấn trừ giá trị hàng lỗi trực tiếp vào công nợ đơn sau.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Defect Rate, Quality Claim, Debit Note, Replacement, SOP.')
