insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c70e85b8-4aeb-52fd-a574-4062857075a1', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 7, 'Nhà cung cấp lâu năm bất ngờ thông báo tăng giá 15% bắt đầu từ đơn hàng sáng mai do giá bột giấy tăng, nếu không đồng ý họ sẽ ngưng cấp hàng, bạn xử lý thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Giữ bình tĩnh & Dùng hợp đồng","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đàm phán Đổi giá trị / Trade-off","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Giữ bình tĩnh & Dùng hợp đồng","description":"Tiêu chí 1 - Giữ bình tĩnh & Dùng hợp đồng (20đ): Không nổi cáu hay bỏ cuộc ngay; yêu cầu văn bản thông báo chính thức kèm chứng từ chứng minh; dùng điều khoản Hợp đồng (báo trước 15-30 ngày) để bắt buộc giữ giá cũ cho đơn sáng mai.","keywords":[],"weight":20,"maxScore":20,"skill":"Giữ bình tĩnh & Dùng hợp đồng"},{"id":"criterion_2","label":"Đàm phán Đổi giá trị / Trade-off","description":"Tiêu chí 2 - Đàm phán Đổi giá trị / Trade-off (20đ): Nếu bắt buộc tăng giá đợt sau, thương lượng tăng thời hạn công nợ (30  60 ngày) hoặc cam kết sản lượng (Volume) lớn hơn để khống chế mức tăng giá ở 5% thay vì 15%.","keywords":[],"weight":20,"maxScore":20,"skill":"Đàm phán Đổi giá trị / Trade-off"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Price Increase Notice, Contract Clause, Trade-off, BATNA, Payment Terms.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Giữ bình tĩnh & Dùng hợp đồng (20đ): Không nổi cáu hay bỏ cuộc ngay; yêu cầu văn bản thông báo chính thức kèm chứng từ chứng minh; dùng điều khoản Hợp đồng (báo trước 15-30 ngày) để bắt buộc giữ giá cũ cho đơn sáng mai.
Tiêu chí 2 - Đàm phán Đổi giá trị / Trade-off (20đ): Nếu bắt buộc tăng giá đợt sau, thương lượng tăng thời hạn công nợ (30  60 ngày) hoặc cam kết sản lượng (Volume) lớn hơn để khống chế mức tăng giá ở 5% thay vì 15%.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Price Increase Notice, Contract Clause, Trade-off, BATNA, Payment Terms.')
