insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('1a330d71-23ee-594b-a855-9afce9750e30', (select id from public.interview_sets where slug = 'r2w-purchasing-20261017'), 8, 'Giữa NCC A (Giá rẻ hơn 5%, trả trước 100%) và NCC B (Giá nhỉnh hơn 5%, trả chậm 30 ngày, giao sớm 2 ngày), bạn chọn bên nào và lập luận trình Sếp ra sao?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Lựa chọn & Lập luận tối ưu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Chỉ ra rủi ro của NCC A","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Lựa chọn & Lập luận tối ưu","description":"Tiêu chí 1 - Lựa chọn & Lập luận tối ưu (20đ): Đề xuất chọn NCC B; chứng minh chênh lệch 5% giá được bù đắp hoàn toàn bởi việc giao hàng sớm 2 ngày (đảm bảo an toàn SLA sản xuất) và trả chậm 30 ngày (tối ưu dòng tiền).","keywords":[],"weight":20,"maxScore":20,"skill":"Lựa chọn & Lập luận tối ưu"},{"id":"criterion_2","label":"Chỉ ra rủi ro của NCC A","description":"Tiêu chí 2 - Chỉ ra rủi ro của NCC A (20đ): Phân tích rủi ro giam vốn khi trả trước 100% và rủi ro chậm tiến độ giao hàng của NCC A.","keywords":[],"weight":20,"maxScore":20,"skill":"Chỉ ra rủi ro của NCC A"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Working Capital, Cash Flow Risk, SLA Margin, Executive Proposal.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Lựa chọn & Lập luận tối ưu (20đ): Đề xuất chọn NCC B; chứng minh chênh lệch 5% giá được bù đắp hoàn toàn bởi việc giao hàng sớm 2 ngày (đảm bảo an toàn SLA sản xuất) và trả chậm 30 ngày (tối ưu dòng tiền).
Tiêu chí 2 - Chỉ ra rủi ro của NCC A (20đ): Phân tích rủi ro giam vốn khi trả trước 100% và rủi ro chậm tiến độ giao hàng của NCC A.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Working Capital, Cash Flow Risk, SLA Margin, Executive Proposal.')
