insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('a882db7b-b5b1-547e-a1f1-5f1a9c27af6b', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 1, 'Giới thiệu bản thân và vì sao bạn chọn nghề Tester/Quality Assurance (QA)', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể kinh nghiệm/dự án đã từng kiểm thử, không nói chung chung.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đặc thù công việc là tìm lỗi, đảm bảo chất lượng, tư duy phản biện - không nhầm với công việc lập trình.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trả lời mạch lạc, dùng được thuật ngữ Bug/Defect, Quality cơ bản.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu cụ thể kinh nghiệm/dự án đã từng kiểm thử, không nói chung chung.
Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Chỉ ra đặc thù công việc là tìm lỗi, đảm bảo chất lượng, tư duy phản biện - không nhầm với công việc lập trình.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trả lời mạch lạc, dùng được thuật ngữ Bug/Defect, Quality cơ bản.')
