values ('7a02ac4a-abb3-5b56-a1c2-0946a3024344', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 2, 'Bạn hãy phân biệt Testing và Quality Assurance', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Định nghĩa đúng Testing","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng QA","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Testing","description":"Tiêu chí 1 - Định nghĩa đúng Testing (15đ): Là hoạt động PHÁT HIỆN lỗi trên sản phẩm cụ thể đã hoàn thành một phần - mang tính phản ứng (reactive).","keywords":[],"weight":15,"maxScore":15,"skill":"Định nghĩa đúng Testing"},{"id":"criterion_2","label":"Định nghĩa đúng QA","description":"Tiêu chí 2 - Định nghĩa đúng QA (12đ): Là tập hợp hoạt động đảm bảo QUY TRÌNH được thực hiện đúng chuẩn để PHÒNG NGỪA lỗi từ đầu - mang tính chủ động (proactive), ví dụ review tài liệu yêu cầu.","keywords":[],"weight":12,"maxScore":12,"skill":"Định nghĩa đúng QA"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ Reactive/Proactive, Quality Assurance/Quality Control.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Định nghĩa đúng Testing (15đ): Là hoạt động PHÁT HIỆN lỗi trên sản phẩm cụ thể đã hoàn thành một phần - mang tính phản ứng (reactive).
Tiêu chí 2 - Định nghĩa đúng QA (12đ): Là tập hợp hoạt động đảm bảo QUY TRÌNH được thực hiện đúng chuẩn để PHÒNG NGỪA lỗi từ đầu - mang tính chủ động (proactive), ví dụ review tài liệu yêu cầu.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ Reactive/Proactive, Quality Assurance/Quality Control.')
