insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('2c6fb345-cf42-513d-8774-dd4a91d816ab', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 3, 'Hãy kể tên các loại kiểm thử bạn biết (Manual, Automation, Unit, Integration...)', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Liệt kê đủ các loại","weight":20,"maxScore":20},{"id":"criterion_2","label":"Giải thích đúng ai thực hiện loại nào, phân biệt rõ trách nhiệm từng vai trò","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ các loại","description":"Tiêu chí 1 - Liệt kê đủ các loại (20đ): Nêu tối thiểu 5/6: Manual, Automation, Unit, Integration, System, UAT.","keywords":[],"weight":20,"maxScore":20,"skill":"Liệt kê đủ các loại"},{"id":"criterion_2","label":"Giải thích đúng ai thực hiện loại nào, phân biệt rõ trách nhiệm từng vai trò","description":"Tiêu chí 2 - Giải thích đúng ai thực hiện loại nào, phân biệt rõ trách nhiệm từng vai trò (10đ):\nUnit Testing thường do Developer (Dev) thực hiện - kiểm tra từng hàm/đơn vị code nhỏ nhất\nIntegration Testing do Developer hoặc Tester thực hiện - kiểm tra khi các module ghép nối với nhau\nSystem Testing do Tester/Quality Assurance (QA) thực hiện - kiểm tra toàn bộ hệ thống hoàn chỉnh, mô phỏng cách người dùng thật sẽ dùng\nManual Testing do Tester/Quality Assurance (QA) thực hiện - thực hiện thủ công, dùng tay click/nhập liệu theo test case\nAutomation Testing do Tester/QA (chuyên về Automation) hoặc Software Development Engineer in Test (SDET) thực hiện - viết script để máy tự chạy test lặp đi lặp lại\nUAT (User Acceptance Testing) do người dùng cuối/khách hàng thực hiện - đây là bước nghiệm thu cuối cùng, khách hàng tự tay dùng thử để xác nhận sản phẩm đúng ý trước khi nhận bàn giao","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích đúng ai thực hiện loại nào, phân biệt rõ trách nhiệm từng vai trò"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ tiếng Anh: Unit, Integration, System, UAT.","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đủ các loại (20đ): Nêu tối thiểu 5/6: Manual, Automation, Unit, Integration, System, UAT.
Tiêu chí 2 - Giải thích đúng ai thực hiện loại nào, phân biệt rõ trách nhiệm từng vai trò (10đ):
Unit Testing thường do Developer (Dev) thực hiện - kiểm tra từng hàm/đơn vị code nhỏ nhất
Integration Testing do Developer hoặc Tester thực hiện - kiểm tra khi các module ghép nối với nhau
System Testing do Tester/Quality Assurance (QA) thực hiện - kiểm tra toàn bộ hệ thống hoàn chỉnh, mô phỏng cách người dùng thật sẽ dùng
Manual Testing do Tester/Quality Assurance (QA) thực hiện - thực hiện thủ công, dùng tay click/nhập liệu theo test case
Automation Testing do Tester/QA (chuyên về Automation) hoặc Software Development Engineer in Test (SDET) thực hiện - viết script để máy tự chạy test lặp đi lặp lại
UAT (User Acceptance Testing) do người dùng cuối/khách hàng thực hiện - đây là bước nghiệm thu cuối cùng, khách hàng tự tay dùng thử để xác nhận sản phẩm đúng ý trước khi nhận bàn giao
Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ tiếng Anh: Unit, Integration, System, UAT.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

