values ('8084078f-1297-51d0-8260-85ab00b119fa', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 4, 'Quy trình viết test case gồm những bước nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","weight":18,"maxScore":18},{"id":"criterion_2","label":"Trình bày theo trình tự logic","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ thành phần cốt lõi","description":"Tiêu chí 1 - Liệt kê đủ thành phần cốt lõi (18đ): ID/tiêu đề, điều kiện tiền đề (pre-condition), dữ liệu đầu vào, các bước thực hiện, kết quả mong đợi (expected result).","keywords":[],"weight":18,"maxScore":18,"skill":"Liệt kê đủ thành phần cốt lõi"},{"id":"criterion_2","label":"Trình bày theo trình tự logic","description":"Tiêu chí 2 - Trình bày theo trình tự logic (10đ): Các bước phải theo đúng thứ tự thực hiện thực tế, không đảo lộn.","keywords":[],"weight":10,"maxScore":10,"skill":"Trình bày theo trình tự logic"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ Pre-condition, Expected Result, Actual Result, Test Steps.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đủ thành phần cốt lõi (18đ): ID/tiêu đề, điều kiện tiền đề (pre-condition), dữ liệu đầu vào, các bước thực hiện, kết quả mong đợi (expected result).
Tiêu chí 2 - Trình bày theo trình tự logic (10đ): Các bước phải theo đúng thứ tự thực hiện thực tế, không đảo lộn.
Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ Pre-condition, Expected Result, Actual Result, Test Steps.')
