values ('91ac9d3d-8629-553b-a99a-2fb95f5e1a56', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 5, 'Phân biệt Black-box và White-box testing', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Định nghĩa đúng Black-box","weight":15,"maxScore":15},{"id":"criterion_2","label":"Định nghĩa đúng White-box","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Định nghĩa đúng Black-box","description":"Tiêu chí 1 - Định nghĩa đúng Black-box (15đ): Kiểm thử dựa trên CHỨC NĂNG/đầu vào-đầu ra, KHÔNG cần biết code bên trong - do Tester thực hiện.","keywords":[],"weight":15,"maxScore":15,"skill":"Định nghĩa đúng Black-box"},{"id":"criterion_2","label":"Định nghĩa đúng White-box","description":"Tiêu chí 2 - Định nghĩa đúng White-box (10đ): Kiểm thử dựa trên CẤU TRÚC CODE bên trong (nhánh, điều kiện) - thường do Developer thực hiện qua Unit Test.","keywords":[],"weight":10,"maxScore":10,"skill":"Định nghĩa đúng White-box"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ Black-box/White-box Testing, Code Coverage.","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Định nghĩa đúng Black-box (15đ): Kiểm thử dựa trên CHỨC NĂNG/đầu vào-đầu ra, KHÔNG cần biết code bên trong - do Tester thực hiện.
Tiêu chí 2 - Định nghĩa đúng White-box (10đ): Kiểm thử dựa trên CẤU TRÚC CODE bên trong (nhánh, điều kiện) - thường do Developer thực hiện qua Unit Test.
Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Dùng đúng thuật ngữ Black-box/White-box Testing, Code Coverage.')
