insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('c2db7e81-6b38-5e6b-b901-6021c074cf33', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 6, 'Bug life cycle gồm những trạng thái nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đúng thứ tự trạng thái chính","weight":20,"maxScore":20},{"id":"criterion_2","label":"Nêu được trạng thái phụ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đúng thứ tự trạng thái chính","description":"Tiêu chí 1 - Liệt kê đúng thứ tự trạng thái chính (20đ): New → Assigned → Fixed → Retest → Closed (kèm nhánh Reopen nếu Retest fail).","keywords":[],"weight":20,"maxScore":20,"skill":"Liệt kê đúng thứ tự trạng thái chính"},{"id":"criterion_2","label":"Nêu được trạng thái phụ","description":"Tiêu chí 2 - Nêu được trạng thái phụ (10đ): Rejected (không phải bug thật) hoặc Deferred (hoãn xử lý sang bản sau).","keywords":[],"weight":10,"maxScore":10,"skill":"Nêu được trạng thái phụ"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Trình bày logic, đúng trình tự, mạch lạc, không dài dòng.","keywords":[],"weight":5,"maxScore":5,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đúng thứ tự trạng thái chính (20đ): New → Assigned → Fixed → Retest → Closed (kèm nhánh Reopen nếu Retest fail).
Tiêu chí 2 - Nêu được trạng thái phụ (10đ): Rejected (không phải bug thật) hoặc Deferred (hoãn xử lý sang bản sau).
Tiêu chí 3 - Từ vựng & Sự tự tin (5đ): Trình bày logic, đúng trình tự, mạch lạc, không dài dòng.')
