insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('72f9cb8c-9805-5bb9-beb8-a0ebf91fdbc3', (select id from public.interview_sets where slug = 'r2w-qa-tester-20261017'), 7, 'Bạn phát hiện bug nghiêm trọng sát ngày release, bạn xử lý ra sao?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Đánh giá đúng mức độ ưu tiên trước khi hành động","weight":20,"maxScore":20},{"id":"criterion_2","label":"Đề xuất phương án cụ thể theo mức độ","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Đánh giá đúng mức độ ưu tiên trước khi hành động","description":"Tiêu chí 1 - Đánh giá đúng mức độ ưu tiên trước khi hành động (20đ): Đánh giá Severity (mức độ nghiêm trọng kỹ thuật) và Priority (mức độ cần xử lý gấp) trước khi quyết định, KHÔNG báo cáo hoảng loạn hoặc im lặng bỏ qua.","keywords":[],"weight":20,"maxScore":20,"skill":"Đánh giá đúng mức độ ưu tiên trước khi hành động"},{"id":"criterion_2","label":"Đề xuất phương án cụ thể theo mức độ","description":"Tiêu chí 2 - Đề xuất phương án cụ thể theo mức độ (20đ): Nếu ảnh hưởng luồng nghiệp vụ chính → đề xuất hoãn release hoặc hotfix khẩn; nếu ảnh hưởng nhỏ → release đúng hạn kèm ghi chú và lên kế hoạch fix bản sau.","keywords":[],"weight":20,"maxScore":20,"skill":"Đề xuất phương án cụ thể theo mức độ"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ Severity, Priority, Hotfix, Critical Bug.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Đánh giá đúng mức độ ưu tiên trước khi hành động (20đ): Đánh giá Severity (mức độ nghiêm trọng kỹ thuật) và Priority (mức độ cần xử lý gấp) trước khi quyết định, KHÔNG báo cáo hoảng loạn hoặc im lặng bỏ qua.
Tiêu chí 2 - Đề xuất phương án cụ thể theo mức độ (20đ): Nếu ảnh hưởng luồng nghiệp vụ chính → đề xuất hoãn release hoặc hotfix khẩn; nếu ảnh hưởng nhỏ → release đúng hạn kèm ghi chú và lên kế hoạch fix bản sau.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ Severity, Priority, Hotfix, Critical Bug.')
