values ('486236dd-e4dd-586a-88f2-ba1828db0cae', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 1, 'Giới thiệu bản thân và vì sao bạn chọn định hướng trở thành Supply Chain Analyst?', '', '{}'::text[], 1, 30, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","weight":12,"maxScore":12},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Nền tảng liên quan cụ thể","description":"Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án phân tích dữ liệu, hệ thống thông tin, mô hình hóa dữ liệu bằng Excel, SQL, Power BI hoặc Python liên quan đến chuỗi cung ứng.","keywords":[],"weight":12,"maxScore":12,"skill":"Nền tảng liên quan cụ thể"},{"id":"criterion_2","label":"Lý do đúng bản chất nghề","description":"Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Hiểu rõ vai trò Analyst là khai thác dữ liệu, phát hiện bất thường, tìm nguyên nhân gốc rễ và đề xuất giải pháp tối ưu; phân biệt với nhân sự vận hành thuần túy.","keywords":[],"weight":10,"maxScore":10,"skill":"Lý do đúng bản chất nghề"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Data Analytics, Inventory Optimization, Supply-Demand, Forecasting.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Nền tảng liên quan cụ thể (12đ): Nêu ngành học/dự án phân tích dữ liệu, hệ thống thông tin, mô hình hóa dữ liệu bằng Excel, SQL, Power BI hoặc Python liên quan đến chuỗi cung ứng.
Tiêu chí 2 - Lý do đúng bản chất nghề (10đ): Hiểu rõ vai trò Analyst là khai thác dữ liệu, phát hiện bất thường, tìm nguyên nhân gốc rễ và đề xuất giải pháp tối ưu; phân biệt với nhân sự vận hành thuần túy.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Trình bày mạch lạc, dùng đúng thuật ngữ: Data Analytics, Inventory Optimization, Supply-Demand, Forecasting.')
