insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('86d484ab-4403-56a1-ae9f-4dc77df2fe2c', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 2, 'Bạn hiểu vai trò của một Supply Chain Analyst trong doanh nghiệp là gì?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Xác định đúng vai trò","weight":15,"maxScore":15},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Xác định đúng vai trò","description":"Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là người biến dữ liệu thô trong chuỗi cung ứng thành thông tin quản trị (Actionable Insights) giúp cải thiện hiệu suất và giảm chi phí.","keywords":[],"weight":15,"maxScore":15,"skill":"Xác định đúng vai trò"},{"id":"criterion_2","label":"Liệt kê đủ đầu việc cốt lõi","description":"Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 công việc: Phân tích tồn kho (DOI/Safety Stock), dự báo nhu cầu (Demand Forecasting), đánh giá KPI nhà cung cấp (OTIF), phân tích chi phí vận chuyển/lưu kho, tìm nguyên nhân gốc rễ đứt gãy.","keywords":[],"weight":12,"maxScore":12,"skill":"Liệt kê đủ đầu việc cốt lõi"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: DOI, Safety Stock, OTIF, Lead Time, Actionable Insights.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Xác định đúng vai trò (15đ): Nêu rõ đây là người biến dữ liệu thô trong chuỗi cung ứng thành thông tin quản trị (Actionable Insights) giúp cải thiện hiệu suất và giảm chi phí.
Tiêu chí 2 - Liệt kê đủ đầu việc cốt lõi (12đ): Nêu tối thiểu 3/5 công việc: Phân tích tồn kho (DOI/Safety Stock), dự báo nhu cầu (Demand Forecasting), đánh giá KPI nhà cung cấp (OTIF), phân tích chi phí vận chuyển/lưu kho, tìm nguyên nhân gốc rễ đứt gãy.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: DOI, Safety Stock, OTIF, Lead Time, Actionable Insights.')
