values ('12f7f4c4-5c3c-5fcd-97bc-9772fd5c930a', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 3, 'Bạn đã từng thực hiện dự án hoặc bài tập phân tích dữ liệu chuỗi cung ứng nào chưa?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","weight":15,"maxScore":15},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","weight":12,"maxScore":12},{"id":"criterion_3","label":"Bài học kinh nghiệm","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Ví dụ dự án cụ thể","description":"Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên bài tập/dự án cụ thể (phân tích tồn kho, dự báo bán hàng, đánh giá nhà cung cấp...), mô tả nguồn dữ liệu và vai trò đảm nhận.","keywords":[],"weight":15,"maxScore":15,"skill":"Ví dụ dự án cụ thể"},{"id":"criterion_2","label":"Trình bày theo cấu trúc STAR","description":"Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động phân tích dữ liệu (Action)  Kết quả đo lường được (Result).","keywords":[],"weight":12,"maxScore":12,"skill":"Trình bày theo cấu trúc STAR"},{"id":"criterion_3","label":"Bài học kinh nghiệm","description":"Tiêu chí 3 - Bài học kinh nghiệm (8đ): Chỉ ra 1 bài học nghiệp vụ, ví dụ: \"phải làm sạch dữ liệu và kiểm tra tính toàn vẹn trước khi đưa ra nhận định\".","keywords":[],"weight":8,"maxScore":8,"skill":"Bài học kinh nghiệm"}]'::jsonb, 'Tiêu chí 1 - Ví dụ dự án cụ thể (15đ): Nêu tên bài tập/dự án cụ thể (phân tích tồn kho, dự báo bán hàng, đánh giá nhà cung cấp...), mô tả nguồn dữ liệu và vai trò đảm nhận.
Tiêu chí 2 - Trình bày theo cấu trúc STAR (12đ): Bối cảnh (Situation)  Nhiệm vụ (Task)  Hành động phân tích dữ liệu (Action)  Kết quả đo lường được (Result).
Tiêu chí 3 - Bài học kinh nghiệm (8đ): Chỉ ra 1 bài học nghiệp vụ, ví dụ: "phải làm sạch dữ liệu và kiểm tra tính toàn vẹn trước khi đưa ra nhận định".')
