values ('24f9d812-2884-5050-8f24-7d22268b1b75', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 4, 'Giải thích Hiệu ứng Bullwhip (Cái roi da) trong chuỗi cung ứng và đề xuất giải pháp cốt lõi để khắc phục?', '', '{}'::text[], 2, 30, '[{"id":"criterion_1","label":"Phân tích đúng nguyên nhân","weight":15,"maxScore":15},{"id":"criterion_2","label":"Giải pháp dựa trên Dữ liệu","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Phân tích đúng nguyên nhân","description":"Tiêu chí 1 - Phân tích đúng nguyên nhân (15đ): Chỉ ra biến động nhu cầu ảo bị khuếch đại qua các tầng (Siêu thị  Đại lý  Nhà máy) do hoảng loạn ngắn hạn và thiếu chia sẻ thông tin.","keywords":[],"weight":15,"maxScore":15,"skill":"Phân tích đúng nguyên nhân"},{"id":"criterion_2","label":"Giải pháp dựa trên Dữ liệu","description":"Tiêu chí 2 - Giải pháp dựa trên Dữ liệu (12đ): Đề xuất thu thập dữ liệu bán hàng thực tế tại điểm bán (POS Data) và chia sẻ tồn kho minh bạch toàn chuỗi (VMI/CPFR).","keywords":[],"weight":12,"maxScore":12,"skill":"Giải pháp dựa trên Dữ liệu"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Bullwhip Effect, Panic Buying, Point of Sale (POS) Data, VMI, CPFR.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Phân tích đúng nguyên nhân (15đ): Chỉ ra biến động nhu cầu ảo bị khuếch đại qua các tầng (Siêu thị  Đại lý  Nhà máy) do hoảng loạn ngắn hạn và thiếu chia sẻ thông tin.
Tiêu chí 2 - Giải pháp dựa trên Dữ liệu (12đ): Đề xuất thu thập dữ liệu bán hàng thực tế tại điểm bán (POS Data) và chia sẻ tồn kho minh bạch toàn chuỗi (VMI/CPFR).
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Bullwhip Effect, Panic Buying, Point of Sale (POS) Data, VMI, CPFR.')
