values ('62b56131-9f53-54dd-ad28-dd09e9febf2d', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 5, 'Các nhóm chỉ số quan trọng thường dùng để phân tích hiệu suất tồn kho và nhà cung cấp là gì?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Liệt kê đủ nhóm chỉ số","weight":18,"maxScore":18},{"id":"criterion_2","label":"Giải thích ý nghĩa nghiệp vụ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Liệt kê đủ nhóm chỉ số","description":"Tiêu chí 1 - Liệt kê đủ nhóm chỉ số (18đ): Số ngày tồn kho (DOI), Điểm đặt hàng lại (ROP), Tồn an toàn (Safety Stock), Tỷ lệ giao đúng hạn đủ lượng (OTIF), Lead Time.","keywords":[],"weight":18,"maxScore":18,"skill":"Liệt kê đủ nhóm chỉ số"},{"id":"criterion_2","label":"Giải thích ý nghĩa nghiệp vụ","description":"Tiêu chí 2 - Giải thích ý nghĩa nghiệp vụ (10đ): Giải thích DOI cao gây ứ đọng vốn, OTIF thấp cảnh báo nguy cơ đứt gãy cung ứng; nêu được mối quan hệ giữa Lead Time và ROP.","keywords":[],"weight":10,"maxScore":10,"skill":"Giải thích ý nghĩa nghiệp vụ"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Days of Inventory (DOI), Reorder Point (ROP), OTIF, Lead Time, Working Capital.","keywords":[],"weight":7,"maxScore":7,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Liệt kê đủ nhóm chỉ số (18đ): Số ngày tồn kho (DOI), Điểm đặt hàng lại (ROP), Tồn an toàn (Safety Stock), Tỷ lệ giao đúng hạn đủ lượng (OTIF), Lead Time.
Tiêu chí 2 - Giải thích ý nghĩa nghiệp vụ (10đ): Giải thích DOI cao gây ứ đọng vốn, OTIF thấp cảnh báo nguy cơ đứt gãy cung ứng; nêu được mối quan hệ giữa Lead Time và ROP.
Tiêu chí 3 - Từ vựng & Sự tự tin (7đ): Dùng đúng thuật ngữ: Days of Inventory (DOI), Reorder Point (ROP), OTIF, Lead Time, Working Capital.')
