insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('ae910094-1327-5ae9-939e-c024bb6abaf7', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 6, 'Khi phát hiện chỉ số DOI của một SKU tăng vọt lên 90 ngày (gấp 6 lần định mức 14 ngày), bạn phân tích nguyên nhân và đề xuất xử lý thế nào?', '', '{}'::text[], 2, 35, '[{"id":"criterion_1","label":"Chẩn đoán nguyên nhân gốc rễ","weight":15,"maxScore":15},{"id":"criterion_2","label":"Đề xuất giải pháp hành động","weight":12,"maxScore":12},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":8,"maxScore":8}]'::jsonb, '[{"id":"criterion_1","label":"Chẩn đoán nguyên nhân gốc rễ","description":"Tiêu chí 1 - Chẩn đoán nguyên nhân gốc rễ (15đ): Đối soát dữ liệu ROP, lịch sử đặt hàng, sai lệch dự báo (Over-forecasting) và xu hướng sụt giảm sức mua thực tế.","keywords":[],"weight":15,"maxScore":15,"skill":"Chẩn đoán nguyên nhân gốc rễ"},{"id":"criterion_2","label":"Đề xuất giải pháp hành động","description":"Tiêu chí 2 - Đề xuất giải pháp hành động (12đ): Lập tức tạm ngưng đặt mua mới  Đề xuất chương trình bán kèm (Bundling), khuyến mãi kích cầu hoặc điều chuyển hàng nội bộ để giải phóng kho.","keywords":[],"weight":12,"maxScore":12,"skill":"Đề xuất giải pháp hành động"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Excess Stock, Over-forecasting, Bundling, Inventory Transfer, Root Cause Analysis.","keywords":[],"weight":8,"maxScore":8,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Chẩn đoán nguyên nhân gốc rễ (15đ): Đối soát dữ liệu ROP, lịch sử đặt hàng, sai lệch dự báo (Over-forecasting) và xu hướng sụt giảm sức mua thực tế.
Tiêu chí 2 - Đề xuất giải pháp hành động (12đ): Lập tức tạm ngưng đặt mua mới  Đề xuất chương trình bán kèm (Bundling), khuyến mãi kích cầu hoặc điều chuyển hàng nội bộ để giải phóng kho.
Tiêu chí 3 - Từ vựng & Sự tự tin (8đ): Dùng đúng thuật ngữ: Excess Stock, Over-forecasting, Bundling, Inventory Transfer, Root Cause Analysis.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3fc89b32-4ecd-58be-bc84-0074ab5c3ee8', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 7, 'Chi phí Logistics tháng này tăng vọt 40%. Sếp yêu cầu bạn giải thích nhanh bằng lời (Data Storytelling) mà không đọc file Excel 1.000 dòng, bạn trình bày thế nào?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Ngôn ngữ Kinh doanh đơn giản","weight":20,"maxScore":20},{"id":"criterion_2","label":"Tìm đúng nguyên nhân có con số","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Ngôn ngữ Kinh doanh đơn giản","description":"Tiêu chí 1 - Ngôn ngữ Kinh doanh đơn giản (20đ): Tuyệt đối không dùng thuật ngữ kỹ thuật rườm rà (Outliers, MAPE); dùng ngôn ngữ tài chính/kinh doanh (Doanh số, Tồn kho, Phí lưu bãi).","keywords":[],"weight":20,"maxScore":20,"skill":"Ngôn ngữ Kinh doanh đơn giản"},{"id":"criterion_2","label":"Tìm đúng nguyên nhân có con số","description":"Tiêu chí 2 - Tìm đúng nguyên nhân có con số (20đ): Giải thích logic: Sales dự báo vượt thực tế làm hàng phơi kho ngoài  phát sinh 40% chi phí lưu kho.","keywords":[],"weight":20,"maxScore":20,"skill":"Tìm đúng nguyên nhân có con số"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Storytelling, Storage Cost, Forecast Error, Executive Summary.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Ngôn ngữ Kinh doanh đơn giản (20đ): Tuyệt đối không dùng thuật ngữ kỹ thuật rườm rà (Outliers, MAPE); dùng ngôn ngữ tài chính/kinh doanh (Doanh số, Tồn kho, Phí lưu bãi).
Tiêu chí 2 - Tìm đúng nguyên nhân có con số (20đ): Giải thích logic: Sales dự báo vượt thực tế làm hàng phơi kho ngoài  phát sinh 40% chi phí lưu kho.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Storytelling, Storage Cost, Forecast Error, Executive Summary.')
on conflict (set_id, position) do update set
  prompt = excluded.prompt,
  guidance = excluded.guidance,
  keywords = excluded.keywords,
  round_number = excluded.round_number,
  max_score = excluded.max_score,
  rubric = excluded.rubric,
  grading_rubric = excluded.grading_rubric,
  reference_answer = excluded.reference_answer;

insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('f194110d-3662-5bb4-bc04-7c3646631597', (select id from public.interview_sets where slug = 'r2w-supply-chain-20261017'), 8, 'Dữ liệu trích xuất từ hệ thống ERP bị thiếu hụt thông tin Lead Time của một số nhà cung cấp, bạn làm gì trước khi đưa ra báo cáo phân tích?', '', '{}'::text[], 3, 50, '[{"id":"criterion_1","label":"Bảo toàn tính toàn vẹn dữ liệu","weight":20,"maxScore":20},{"id":"criterion_2","label":"Minh bạch giả định & Cảnh báo","weight":20,"maxScore":20},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","weight":10,"maxScore":10}]'::jsonb, '[{"id":"criterion_1","label":"Bảo toàn tính toàn vẹn dữ liệu","description":"Tiêu chí 1 - Bảo toàn tính toàn vẹn dữ liệu (20đ): Tuyệt đối không tự bịa số liệu; tiến hành đối soát chéo với Bộ phận Thu mua/Kho để làm sạch dữ liệu.","keywords":[],"weight":20,"maxScore":20,"skill":"Bảo toàn tính toàn vẹn dữ liệu"},{"id":"criterion_2","label":"Minh bạch giả định & Cảnh báo","description":"Tiêu chí 2 - Minh bạch giả định & Cảnh báo (20đ): Đánh dấu rõ vùng dữ liệu chưa chắc chắn, ghi chú giả định (Assumptions) và nêu rõ mức độ ảnh hưởng đến kết quả phân tích.","keywords":[],"weight":20,"maxScore":20,"skill":"Minh bạch giả định & Cảnh báo"},{"id":"criterion_3","label":"Từ vựng & Sự tự tin","description":"Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Cleaning, Data Integrity, Cross-validation, Assumptions.","keywords":[],"weight":10,"maxScore":10,"skill":"Từ vựng & Sự tự tin"}]'::jsonb, 'Tiêu chí 1 - Bảo toàn tính toàn vẹn dữ liệu (20đ): Tuyệt đối không tự bịa số liệu; tiến hành đối soát chéo với Bộ phận Thu mua/Kho để làm sạch dữ liệu.
Tiêu chí 2 - Minh bạch giả định & Cảnh báo (20đ): Đánh dấu rõ vùng dữ liệu chưa chắc chắn, ghi chú giả định (Assumptions) và nêu rõ mức độ ảnh hưởng đến kết quả phân tích.
Tiêu chí 3 - Từ vựng & Sự tự tin (10đ): Dùng đúng thuật ngữ: Data Cleaning, Data Integrity, Cross-validation, Assumptions.')
on conflict (set_id, position) do update set
