insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('3146bf9b-50c9-591c-9350-60428a015f5a', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261017'), 2, 'Theo bạn, trợ lý thuế cần có những kỹ năng quan trọng nào?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","weight":20,"maxScore":20},{"id":"criterion_2","label":"Kiểm tra chứng từ","weight":10,"maxScore":10},{"id":"criterion_3","label":"Cập nhật quy định","weight":5,"maxScore":5}]'::jsonb, '[{"id":"criterion_1","label":"Kiến thức thuế cơ bản","description":"Tiêu chí 1 - Kiến thức thuế cơ bản (20đ): Hiểu sự cần thiết của kiến thức về các sắc thuế và quy định liên quan.","keywords":[],"weight":20,"maxScore":20,"skill":"Kiến thức thuế cơ bản"},{"id":"criterion_2","label":"Kiểm tra chứng từ","description":"Tiêu chí 2 - Kiểm tra chứng từ (10đ): Biết kiểm tra hóa đơn, chứng từ và đối chiếu số liệu.","keywords":[],"weight":10,"maxScore":10,"skill":"Kiểm tra chứng từ"},{"id":"criterion_3","label":"Cập nhật quy định","description":"Tiêu chí 3 - Cập nhật quy định (5đ): Nhận thức chính sách thuế có thể thay đổi.","keywords":[],"weight":5,"maxScore":5,"skill":"Cập nhật quy định"}]'::jsonb, 'Tiêu chí 1 - Kiến thức thuế cơ bản (20đ): Hiểu sự cần thiết của kiến thức về các sắc thuế và quy định liên quan.
Tiêu chí 2 - Kiểm tra chứng từ (10đ): Biết kiểm tra hóa đơn, chứng từ và đối chiếu số liệu.
Tiêu chí 3 - Cập nhật quy định (5đ): Nhận thức chính sách thuế có thể thay đổi.')
