insert into public.interview_questions (id, set_id, position, prompt, guidance, keywords, round_number, max_score, rubric, grading_rubric, reference_answer)
values ('31f260bf-2521-5362-a68d-676420dd1bce', (select id from public.interview_sets where slug = 'r2w-tro-ly-thue-20261017'), 3, 'Vì sao việc cập nhật các quy định thuế lại quan trọng đối với một trợ lý thuế?', '', '{}'::text[], 1, 35, '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","weight":18,"maxScore":18},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","weight":10,"maxScore":10},{"id":"criterion_3","label":"Chủ động cập nhật","weight":7,"maxScore":7}]'::jsonb, '[{"id":"criterion_1","label":"Nhận thức về thay đổi chính sách","description":"Tiêu chí 1 - Nhận thức về thay đổi chính sách (18đ): Hiểu quy định thuế có thể được cập nhật/thay đổi. Hiểu quy định thuế có thể được cập nhật/thay đổi.","keywords":[],"weight":18,"maxScore":18,"skill":"Nhận thức về thay đổi chính sách"},{"id":"criterion_2","label":"Ảnh hưởng đến công việc","description":"Tiêu chí 2 - Ảnh hưởng đến công việc (10đ): Biết thay đổi chính sách có thể ảnh hưởng đến cách kê khai và xử lý hồ sơ","keywords":[],"weight":10,"maxScore":10,"skill":"Ảnh hưởng đến công việc"},{"id":"criterion_3","label":"Chủ động cập nhật","description":"Tiêu chí 3 - Chủ động cập nhật (7đ): Nêu được cách cập nhật từ nguồn chính thống, tài liệu chuyên môn hoặc hướng dẫn của doanh nghiệp.","keywords":[],"weight":7,"maxScore":7,"skill":"Chủ động cập nhật"}]'::jsonb, 'Tiêu chí 1 - Nhận thức về thay đổi chính sách (18đ): Hiểu quy định thuế có thể được cập nhật/thay đổi. Hiểu quy định thuế có thể được cập nhật/thay đổi.
Tiêu chí 2 - Ảnh hưởng đến công việc (10đ): Biết thay đổi chính sách có thể ảnh hưởng đến cách kê khai và xử lý hồ sơ
Tiêu chí 3 - Chủ động cập nhật (7đ): Nêu được cách cập nhật từ nguồn chính thống, tài liệu chuyên môn hoặc hướng dẫn của doanh nghiệp.')
